INSERT INTO public.economics_cases
  (subsection, case_id, title, context, statements, answer_key, tactical_explanations, difficulty_level, sort_order, tier)
VALUES
( '2.1', 'CASE 2.1.01', 'Scarcity and economising', 'Evaluate claims about scarcity, economising, and economic participation:', ARRAY['Scarcity disappears once a household earns a steady salary because income removes all limits.', 'Economising means making careful use of limited resources rather than treating them as if they were unlimited.', 'Nobody can fully opt out of economic decisions, because even inaction is a choice about scarce time or money.', 'Only registered businesses face scarcity; households with regular income never need to economise on their spending.', 'Exchange requires that at least one party is an entrepreneur; households can never participate directly in exchange.'], ARRAY[false, true, true, false, false], ARRAY['FALSE — Even steady income is finite and must be allocated among competing needs and wants.', 'TRUE — Economising is the rational response to scarcity: using limited resources as efficiently as possible.', 'TRUE — Choosing not to spend or not to act still allocates a scarce resource and therefore counts as an economic decision.', 'FALSE — Households also face limited budgets and must economise; scarcity is not confined to businesses.', 'FALSE — Households routinely exchange money or goods for products and services; they are active trading partners.'], '3/5', 1, 'full' ),
( '2.1', 'CASE 2.1.02', 'Goods, services, needs, and wants', 'Analyze the distinction between goods, services, needs, and wants:', ARRAY['Goods must be intangible; any tangible item automatically counts as a service instead.', 'Services are intangible activities performed for someone, such as installing software or preparing a drink.', 'Needs are things necessary for well-being, whereas wants are desired but not essential for basic well-being.', 'Both households and businesses have needs that may be fulfilled through exchange with other economic actors.', 'Scarcity means resources are limited, so individuals and businesses must economise rather than assume unlimited supply.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Tangible physical items are goods; intangibility defines services, not the reverse.', 'TRUE — Services are activities performed for a customer rather than physical objects taken away.', 'TRUE — Needs concern necessity for well-being; wants are preferences that go beyond what is strictly necessary.', 'TRUE — Entrepreneurs and firms have operational needs just as households do, such as supplies and labour.', 'TRUE — Limited resources force economising behaviour on both households and businesses facing scarcity.'], '2/5', 2, 'full' ),
( '2.1', 'CASE 2.1.03', 'Households, entrepreneurs, and everyday exchange', 'Evaluate the following economic assertions:', ARRAY['Only consumers ever exchange goods; businesses are legally barred from all trade with households.', 'Only individual consumers have needs; registered businesses operate with zero internal needs of their own.', 'Choosing to keep pocket money unspent means a teenager has avoided making any economic decision.', 'Exchange is one way needs and wants get fulfilled when households and businesses trade with each other.', 'Because money is used, barter arrangements can never count as genuine exchange.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Businesses and households routinely trade goods and services with each other in markets.', 'FALSE — Businesses and entrepreneurs also have operational needs, such as raw materials and a workforce, not only consumers.', 'FALSE — Saving or holding cash is itself a choice about how to use a scarce resource.', 'TRUE — Exchange is precisely how needs and wants on both sides of a transaction can be fulfilled.', 'FALSE — Exchange includes barter where no money changes hands; monetary payment is not required for a trade to count.'], '3/5', 3, 'full' ),
( '2.1', 'CASE 2.1.04', 'Business Operations and Institutional Needs', 'Consider households, startups, and manufacturing firms interacting in a market system. Evaluate:', ARRAY['Businesses provide goods like computers and services like installing software for people to satisfy their needs.', 'Manufacturers of smartphones might have an operational need for printed circuit boards produced by suppliers such as AT&S.', 'To fabricate components, a manufacturer requires raw materials and a workforce rather than operating in isolation.', 'Individuals frequently exchange goods and services directly and are fully active participants in trading.', 'Households need food, shelter, and medical care, and they also want leisure activities such as cinema visits.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Firms supply tangible goods and intangible services that help consumers satisfy needs.', 'TRUE — Component manufacturers depend on specialised inputs such as PCBs to assemble finished devices.', 'TRUE — Production requires limited inputs and labour; no firm can operate without securing those resources.', 'TRUE — Individuals trade with businesses and with each other; households are not excluded from exchange.', 'TRUE — Household demand spans essential needs and non-essential wants such as entertainment.'], '3/5', 4, 'full' ),
( '2.1', 'CASE 2.1.05', 'Corner café: beans and cappuccinos', 'At a corner café customers buy bean bags and pay baristas to prepare cappuccinos. Evaluate:', ARRAY['The bag of roasted beans is a good and the barista''s drink preparation is a service.', 'Needs and wants are identical concepts, so there is no meaningful difference between craving caffeine and a flavoured latte.', 'A habitual craving for a particular drink is more accurately a want if it is not essential for basic well-being.', 'Because the café is a business, it cannot itself be said to have needs such as reliable suppliers.', 'Paying for beans or drinks fulfils needs or wants through exchange on both sides of the transaction.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Beans are tangible goods; preparing and serving a drink is a service performed for the customer.', 'FALSE — Needs concern necessity for well-being; wants are desired but not essential, so the concepts differ.', 'TRUE — A preferred drink beyond basic nutrition is typically classified as a want rather than a strict need.', 'FALSE — Businesses have operational needs including suppliers, staff, and premises to stay open.', 'TRUE — Monetary payment for goods or services is exchange that satisfies needs or wants.'], '2/5', 5, 'full' ),
( '2.1', 'CASE 2.1.06', 'Jonas: bus pass or game skin', 'Jonas has twelve euros pocket money and must choose between an eight-euro bus pass and a ten-euro game skin. Evaluate:', ARRAY['The bus pass is a need for getting to school, while the game skin is a want rather than a basic necessity.', 'Because both items have a price, they must both be classified as needs rather than wants.', 'Individuals face economic decisions about scarce resources even before they run a business or register as entrepreneurs.', 'Choosing to save the twelve euros and buy nothing means Jonas has opted out of all economic decision-making.', 'Once Jonas buys the bus pass, his want for the game skin permanently disappears and can never return.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Needs are necessary for well-being; getting to school is a need, while a game skin is a desired but non-essential want.', 'FALSE — Having a price does not make something a need; the distinction rests on necessity for well-being, not on cost.', 'FALSE — Individuals with pocket money already participate in the economy and face choices about limited resources.', 'FALSE — Saving or doing nothing is itself an economic decision about how to use a scarce resource.', 'FALSE — Satisfying one need does not erase a want; Jonas may still want the skin even after buying the pass.'], '3/5', 6, 'full' ),
( '2.1', 'CASE 2.1.07', 'PhoneFix screen repairs', 'PhoneFix Wien replaces cracked screens using spare parts ordered in limited monthly batches. Evaluate:', ARRAY['Screen replacement is a service, while a phone case sold at the counter is a good.', 'Because PhoneFix is a business rather than a household, its monthly spare parts can never run scarce.', 'A customer buying a decorative case purely for its design is satisfying a want rather than a basic need.', 'Repairing a phone never fulfils a need because phones are luxury items outside normal economic analysis.', 'A limited monthly batch of parts forces the shop to economise by prioritising which jobs to accept.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Repair work is an activity performed on the device (service); a case is a tangible product (good).', 'FALSE — A fixed monthly batch is by definition limited and therefore scarce.', 'TRUE — Buying for design enjoyment rather than necessity reflects a want, not a strict need.', 'FALSE — A working phone for daily communication can represent a genuine household need.', 'TRUE — Scarce spare parts require prioritisation and careful allocation among repair jobs.'], '2/5', 7, 'full' ),
( '2.1', 'CASE 2.1.08', 'Defining the economy from scratch', 'During a first lesson students list core building blocks of economic life. Evaluate:', ARRAY['The economy consists essentially of households and entrepreneurs interacting with one another.', 'Goods are tangible items, whereas services are intangible activities performed for someone.', 'Both households and businesses have needs, and exchange is one way those needs and wants get fulfilled.', 'Scarcity forces individuals and businesses to economise rather than assume unlimited resources.', 'Nobody, whether a household or a business, can truly opt out of making economic decisions.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Households and entrepreneurs are the two foundational groups in the basic economic picture.', 'TRUE — Tangible versus intangible is the core distinction between goods and services.', 'TRUE — Needs and wants on both sides motivate exchange between households and firms.', 'TRUE — Limited resources relative to wants make economising necessary for all actors.', 'TRUE — Even choosing inaction allocates scarce resources and therefore remains an economic decision.'], '2/5', 8, 'full' ),
( '2.1', 'CASE 2.1.09', 'Herr Novak''s bakery', 'Herr Novak sells bread at his Linz bakery and charges one euro extra for doorstep delivery. Evaluate:', ARRAY['Herr Novak acts as an entrepreneur, while the families buying his bread act as households.', 'Bread is a good and doorstep delivery is a service, matching the distinction between tangible and intangible offerings.', 'Because Herr Novak owns a business, he personally has no needs of his own.', 'Paying for delivery is not exchange because a service has no monetary value once it has been performed.', 'Flour and oven fuel are unlimited for any bakery, so Herr Novak never has to economise on ingredients.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — A shop owner supplying products is an entrepreneur; customers purchasing them are households.', 'TRUE — Bread is tangible and therefore a good; delivery is an activity performed and therefore a service.', 'FALSE — Entrepreneurs have needs too, such as reliable suppliers, staff, and premises to keep operating.', 'FALSE — Paying money for a service is a standard form of exchange, just like paying for a good.', 'FALSE — Ingredients and fuel are limited, purchasable resources that any bakery must economise on.'], '2/5', 9, 'full' ),
( '2.1', 'CASE 2.1.10', 'Exchange without money', 'Assess statements about exchange, barter, and fulfilling needs:', ARRAY['Two neighbours swapping gardening lessons for a handmade bookshelf still counts as exchange even without money.', 'Exchange can only occur when euro banknotes or electronic transfers are used between the parties.', 'Wood used to build the bookshelf is a limited resource, so the carpenter must economise on how much he uses.', 'Gardening lessons are a service because they are an activity performed for the neighbour, not a physical item.', 'Individuals, not only businesses, have needs and wants that direct exchange can help satisfy.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Barter still fulfils needs or wants on both sides and therefore qualifies as exchange.', 'FALSE — Exchange is not limited to monetary transactions; barter is a recognised form of trade.', 'TRUE — Raw materials like wood are scarce and require careful allocation across projects.', 'TRUE — Lessons are intangible activities performed for someone and are classified as services.', 'TRUE — Households and individuals participate in exchange and hold needs and wants like firms do.'], '3/5', 10, 'full' ),
( '2.1', 'CASE 2.1.11', 'Petra''s dining table commission', 'Petra pays carpenter Fabian 650 euros for an oak dining table he builds and delivers. Evaluate:', ARRAY['Petra''s family acts as a household and Fabian acts as an entrepreneur in this transaction.', 'The finished dining table is a good because it is a tangible item Fabian produces and delivers.', 'Paying for the table fulfils the family''s need for furniture through exchange.', 'Fabian has no genuine need for timber because raw materials are merely wants for any business.', 'Timber is a limited resource, so Fabian must economise on how much oak he uses per commission.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — A family buying a custom product is a household; a self-employed craftsperson is an entrepreneur.', 'TRUE — A physical table handed over to the buyer is a tangible good.', 'TRUE — Money paid for the table is exchange that fulfils the household''s need for usable furniture.', 'FALSE — Businesses have real needs for inputs such as timber to continue operating and fulfilling orders.', 'TRUE — Timber supply is limited and costly, requiring economising on material use.'], '3/5', 11, 'full' ),
( '2.1', 'CASE 2.1.12', 'Needs, wants, and who has them', 'Evaluate the following assertions about needs, wants, and economic actors:', ARRAY['A manufacturer of laptops may need printed circuit boards from a supplier like AT&S to keep production running.', 'High-tech manufacturers have zero internal needs because only end consumers ever experience genuine need.', 'Households buy goods and services from businesses to satisfy both needs and wants in daily life.', 'Wants disappear automatically once every need has been fully satisfied in a given month.', 'Teenagers with pocket money are outside the economy until they register a business or join a formal household.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Firms have operational needs for inputs such as components and materials to manufacture products.', 'FALSE — Businesses have genuine operational needs for inputs, labour, and customers, not only final consumers.', 'TRUE — Households routinely purchase goods and services from firms to meet needs and wants.', 'FALSE — Wants can persist even after needs are met; satisfying one does not erase the other category.', 'FALSE — Individuals participate economically through consumption and choice long before becoming entrepreneurs.'], '2/5', 12, 'full' ),
( '2.1', 'CASE 2.1.13', 'Lukas end-of-month pocket money', 'Student Lukas has 300 euros monthly for transport, toiletries, and designer trainers. Evaluate:', ARRAY['Ninety euros for transport and toiletries covers needs, while 140-euro trainers cover a want.', 'Because Lukas receives money from parents, he is not part of the household side of the economy.', 'Buying trainers makes his need for transport disappear for the rest of the month.', 'Wanting trainers is irrational and therefore falls outside the scope of economics entirely.', 'A fixed monthly sum is an unlimited resource that never needs to be economised.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Transport and toiletries are necessary; designer trainers are desired but not essential.', 'FALSE — Receiving parental support does not exclude Lukas from household consumption decisions.', 'FALSE — One purchase does not eliminate ongoing needs such as transport for the month.', 'FALSE — Economics studies wants as well as needs; non-essential desires are within its scope.', 'FALSE — A capped monthly allowance remains limited and requires allocation choices.'], '3/5', 13, 'full' ),
( '2.1', 'CASE 2.1.14', 'Farmer Reinisch''s market stall', 'Farmer Reinisch sells potatoes and carrots from eight hectares at a Saturday village market. Evaluate:', ARRAY['Reinisch acts as an entrepreneur at the stall while village buyers act as households.', 'Because farmland can theoretically be bought elsewhere, Reinisch''s eight hectares should not be treated as scarce.', 'Potatoes and carrots are goods rather than services even though they must be cooked before eating.', 'Splitting eight hectares between crops is an economic decision Reinisch cannot avoid given limited land.', 'Paying cash at the stall is not genuine exchange because only barter counts as real economic trade.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — A producer selling at market is an entrepreneur; purchasing families are households.', 'FALSE — Reinisch''s actual eight hectares remain fixed and scarce for his planting decisions regardless of land elsewhere.', 'TRUE — Vegetables are tangible items and therefore goods, regardless of preparation before consumption.', 'TRUE — Fixed acreage forces allocation between competing crop uses.', 'FALSE — Cash payment for produce is a standard monetary form of exchange.'], '2/5', 14, 'full' ),
( '2.1', 'CASE 2.1.15', 'Market day in Hallstatt', 'Toni sells cheese wheels; Rosa offers children''s face-painting; families buy for groceries or fun. Evaluate:', ARRAY['Toni and Rosa act as entrepreneurs while visiting families act as households.', 'A cheese wheel is a good and face-painting is a service.', 'Buying cheese for weekly groceries satisfies a need, while face-painting satisfies more of a want.', 'Paying for cheese or face-painting fulfils needs or wants through exchange on both sides.', 'Because Toni has only thirty wheels left, he must economise by allocating stock among queuing families.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Stallholders supply goods or services; buyers are households purchasing them.', 'TRUE — Cheese is tangible; face-painting is an activity performed on the customer.', 'TRUE — Weekly food is a need; optional entertainment is a want.', 'TRUE — Monetary payment for goods or services is exchange fulfilling needs or wants.', 'TRUE — A fixed remaining stock is a scarce resource requiring careful allocation.'], '2/5', 15, 'full' ),
( '2.1', 'CASE 2.1.16', 'Scarcity across actors', 'Assess whether scarcity and economising apply uniformly:', ARRAY['A multinational corporation with large cash reserves still faces scarce managerial attention and factory capacity.', 'Households never economise because their wants are unlimited and budgets therefore do not constrain them.', 'Governments are excluded from scarcity because they can always raise taxes to fund any project immediately.', 'Economising is rational behaviour when a resource is limited relative to competing uses.', 'Entrepreneurs must economise on inputs such as labour hours and raw materials to stay viable.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Even cash-rich firms face limited time, capacity, and attention among competing projects.', 'FALSE — Household budgets are finite and force trade-offs between competing wants and needs.', 'FALSE — Governments face budget limits within a given period and must allocate among projects.', 'TRUE — Economising responds directly to scarcity by prioritising among alternative uses.', 'TRUE — Firms allocate limited inputs across production, hiring, and investment choices.'], '3/5', 16, 'full' ),
( '2.1', 'CASE 2.1.17', 'Kaffee Ecke morning queue', 'Owner Sami sells bean bags and employs baristas; a rare Ethiopian lot is limited to forty kilograms. Evaluate:', ARRAY['Sami supplies goods and services as an entrepreneur while customers act as households.', 'The bean bag is a good and espresso preparation is a service.', 'A strong habitual coffee craving may reflect a want rather than a strict survival need.', 'Trying a new seasonal flavour for enjoyment is best classified as a want.', 'The forty-kilogram cap forces Sami to economise on how he allocates beans across the season.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — A shop owner providing products and drinks is an entrepreneur; buyers are households.', 'TRUE — Beans are tangible goods; drink preparation is a service.', 'TRUE — Habitual preference beyond basic nutrition typically qualifies as a want.', 'TRUE — Seasonal flavour trials for pleasure are wants, not necessities.', 'TRUE — A fixed bean batch is scarce and requires seasonal allocation decisions.'], '3/5', 17, 'full' ),
( '2.1', 'CASE 2.1.18', 'Classmates swap novels for algebra help', 'Nora lends Felix novels; Felix tutors her two afternoons with no money exchanged. Evaluate:', ARRAY['Exchange requires money, so this novels-for-tutoring swap does not count as exchange at all.', 'Felix''s tutoring is a service and Nora''s novels are goods, matching the standard classification.', 'Because both are students rather than businesses, needs, wants, and exchange concepts do not apply.', 'Felix''s limited free time is a scarce resource allocated between tutoring and his other commitments.', 'Once the swap is agreed, both have opted out of any further economic decisions about their time.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — Exchange includes barter; money is not a prerequisite for a trade that fulfils needs or wants.', 'TRUE — Novels are tangible items (goods); tutoring is an activity performed (service).', 'FALSE — Economic concepts apply to individuals and students, not only to registered firms.', 'TRUE — Time is limited and must be allocated among competing uses.', 'FALSE — Agreeing to one swap does not end ongoing choices about remaining time and resources.'], '3/5', 18, 'full' ),
( '2.1', 'CASE 2.1.19', 'Opting out of the economy?', 'Analyze whether anyone can avoid economic decisions:', ARRAY['Retired couples growing their own food still face scarcity of land, time, and seed and must economise.', 'Repairing a customer''s bicycle at a workshop is a service because it is work performed rather than an item handed over.', 'Selling surplus eggs to neighbours for cash is exchange that fulfils buyers'' needs or wants.', 'Because retirees no longer earn wages, they must be classified as entrepreneurs rather than households.', 'Deciding how much land to plant versus how many chickens to keep is an unavoidable economic choice.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Even subsistence living involves limited land, time, and inputs that must be allocated carefully.', 'TRUE — Activities performed for a customer are services even when physical parts are attached.', 'TRUE — Trading eggs for money is exchange even on a small scale between neighbours.', 'FALSE — Retirement status does not turn a household into an entrepreneur; role depends on the activity, not age.', 'TRUE — Splitting limited land and animals between competing uses is a classic scarce-resource decision.'], '4/5', 19, 'full' ),
( '2.1', 'CASE 2.1.20', 'Remote cabin and firewood trade', 'Karl lives in a remote cabin and occasionally trades firewood for canned food from hikers. Evaluate:', ARRAY['The occasional firewood-for-food trade is exchange fulfilling needs even without shops nearby.', 'Because Karl avoids shops, he has genuinely opted out of making economic decisions.', 'Karl''s claim that he needs nobody proves scarcity no longer applies to him personally.', 'Chopping firewood requires no economising because forests are unlimited resources for anyone living remotely.', 'Only members of registered businesses or official households are affected by needs, wants, and scarcity.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Barter with hikers still fulfils needs through direct exchange.', 'FALSE — Remote living still involves choices about firewood, food, and time.', 'FALSE — Scarcity of labour, food, and firewood still applies regardless of social isolation.', 'FALSE — Accessible firewood and labour effort remain limited and require allocation.', 'FALSE — Economic concepts apply to individuals generally, not only formally registered units.'], '4/5', 20, 'full' ),
( '2.1', 'CASE 2.1.21', 'Electrician Boris and the Hoffmanns', 'The Hoffmanns pay Boris 180 euros for kitchen wiring; that evening Boris buys groceries for his family. Evaluate:', ARRAY['The Hoffmanns act as a household paying for repair; Boris acts as an entrepreneur supplying it.', 'Electrical repair is a service because it is work performed rather than a physical item delivered.', 'Faulty wiring created a need for a working system fulfilled through exchange of money for service.', 'When Boris buys groceries later, he acts as a household with needs of his own.', 'Boris''s limited working hours are a scarce resource he must economise across jobs.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — A family purchasing repair is a household; a tradesperson supplying it is an entrepreneur.', 'TRUE — Repair work is an activity performed on the property and is a service.', 'TRUE — A functioning electrical system is a need met by paying for professional repair.', 'TRUE — The same person can be entrepreneur in one transaction and household in another.', 'TRUE — Limited hours force prioritisation among competing repair jobs.'], '3/5', 21, 'full' ),
( '2.1', 'CASE 2.1.22', 'Goods versus services traps', 'Evaluate fine-grained claims about classifying economic offerings:', ARRAY['Installing software on a customer''s computer is a service, not a good, even though it involves a physical machine.', 'A downloadable e-book file is a service because it has no weight and therefore cannot be a good.', 'Only goods, never services, can be exchanged in a market between households and firms.', 'A restaurant meal eaten on the premises is a good because food is always tangible.', 'Delivery of a pizza to a customer''s door converts the pizza from a service into a good.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Software installation is an activity performed for the customer and is classified as a service.', 'FALSE — Digital products can still be goods when they are transferable items, even without physical weight.', 'FALSE — Services such as repairs, haircuts, and transport are routinely exchanged for payment.', 'FALSE — A prepared meal served and consumed on site is typically the service of catering, not merely a good.', 'FALSE — Delivery is a service added to a good; classification of the pizza itself does not flip categories.'], '4/5', 22, 'full' ),
( '2.1', 'CASE 2.1.23', 'Street musician tips', 'Elena busks on the main square; listeners drop coins into her case for violin performances. Evaluate:', ARRAY['Elena''s performance is a service because it is an activity enjoyed rather than a physical item handed over.', 'Listeners paying because they enjoy the atmosphere are satisfying a want rather than a basic survival need.', 'Because each tip amount is voluntary and unfixed, no exchange takes place between Elena and the listeners.', 'Elena''s need to cover rent shows that individuals, not only registered businesses, experience economic needs.', 'Elena''s limited performing time each Sunday is a scarce resource she must economise across locations.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Live music is an intangible activity supplied to listeners and classified as a service.', 'TRUE — Enjoying atmosphere is not essential to survival and therefore reflects a want.', 'FALSE — Voluntary payment still constitutes exchange when money is given in return for the performance.', 'TRUE — Individuals face needs such as housing costs regardless of whether they operate a formal company.', 'TRUE — Limited hours force a choice about where and when to perform for the best return.'], '3/5', 23, 'full' ),
( '2.1', 'CASE 2.1.24', 'Hair salon: cut versus shampoo', 'Sabine pays twenty-five euros for a haircut and may buy a shampoo bottle at the counter. Evaluate:', ARRAY['The haircut is a service and the shampoo bottle is a good.', 'Because Sabine pays for both with money, both must be classified as goods rather than services.', 'Timo the self-employed hairdresser has no needs of his own since he is on the entrepreneur side.', 'Sabine''s regular six-week visits mean scarcity no longer applies because the purchase became routine.', 'Paying for either item still involves exchange that can fulfil a need or want.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — An activity performed on a person is a service; a bottle taken home is a good.', 'FALSE — Payment method does not determine classification; a paid haircut remains a service.', 'FALSE — Entrepreneurs have personal and business needs despite their role as suppliers.', 'FALSE — Routine repetition does not eliminate scarcity of time and money on each decision.', 'TRUE — Monetary payment for a good or service is exchange fulfilling needs or wants.'], '4/5', 24, 'full' ),
( '2.1', 'CASE 2.1.25', 'Exchange breadth', 'Evaluate sweeping claims about who may exchange and how:', ARRAY['Households exchange with firms when they buy groceries, and with other households when they sell used furniture.', 'Only entrepreneurs are entitled to exchange; households may consume but never trade.', 'Barter between two individuals still counts as exchange when each gives something the other values.', 'Exchange always requires a written contract registered with a government authority to be valid.', 'Paying with a mobile app transfer is exchange just like paying with coins or banknotes.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Households trade with businesses and can trade with each other in second-hand markets.', 'FALSE — Households are active traders when they purchase, sell, or barter goods and services.', 'TRUE — Non-monetary swaps that fulfil needs or wants qualify as exchange.', 'FALSE — Everyday purchases do not require formal contracts to constitute exchange.', 'TRUE — Electronic payment is a monetary form of exchange like cash.'], '3/5', 25, 'full' ),
( '2.1', 'CASE 2.1.26', 'Soup kitchen volunteers', 'Volunteers cook free soup using donated vegetables and a church kitchen lent at no charge. Evaluate:', ARRAY['Because soup is free, no recipient need is fulfilled and no exchange occurs in any sense.', 'Donated vegetables, kitchen time, and volunteer labour are limited and require economising.', 'Absence of money means volunteers and recipients have fully opted out of economic decisions.', 'Choosing which vegetables to use first is an unavoidable economic decision given limited supplies.', 'The church lending its kitchen has no needs of its own because it is not a for-profit business.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — Free provision can still fulfil recipients'' need for food even without a price tag.', 'TRUE — Donated inputs and volunteer time remain scarce relative to how many people could be fed.', 'FALSE — Lack of money does not remove choices about allocating limited resources.', 'TRUE — Portion sizes and ingredient order reflect scarce-resource allocation decisions.', 'FALSE — Non-profit organisations still have needs, such as getting their kitchen back for other uses.'], '3/5', 26, 'full' ),
( '2.1', 'CASE 2.1.27', 'Needs of businesses', 'Analyze whether firms and entrepreneurs experience needs:', ARRAY['A smartphone assembler needs printed circuit boards from specialised suppliers to manufacture devices.', 'Businesses have zero internal needs because only final consumers experience genuine need.', 'An entrepreneur needs customers and revenue to keep staff employed and operations running.', 'Operational needs of firms include workforce, premises, and raw materials, not only consumer demand.', 'If a firm is profitable, scarcity no longer applies to any of its inputs.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Production relies on component inputs that firms genuinely need to assemble finished products.', 'FALSE — Firms have operational needs for inputs, labour, and sales, not only end consumers.', 'TRUE — Without customers and revenue, a business cannot sustain employment and operations.', 'TRUE — Firms require physical and human inputs as needs distinct from household consumption needs.', 'FALSE — Profitability does not make inputs unlimited; capacity and materials remain scarce.'], '2/5', 27, 'full' ),
( '2.1', 'CASE 2.1.28', 'Cannot opt out', 'Evaluate whether economic decision-making can be avoided:', ARRAY['Choosing to hoard cash under a mattress is still an economic decision about using a scarce resource.', 'Only people who run businesses make economic decisions; pure consumers never face scarcity.', 'Doing nothing with a weekly allowance is opting out of economics because no purchase occurred.', 'Retirees living on a pension no longer make economic decisions because income is guaranteed.', 'Children too young to earn wages are entirely outside economic life and never economise.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Saving or hoarding allocates scarce money and is an economic choice.', 'FALSE — Consumers constantly decide how to spend limited income and time.', 'FALSE — Not spending is itself a decision about resource allocation.', 'FALSE — Pensioners still choose how to allocate fixed income among competing uses.', 'FALSE — Children with limited toys, time, or pocket money already face scarcity and choices.'], '4/5', 28, 'full' ),
( '2.1', 'CASE 2.1.29', 'Household wants beyond basics', 'Assess the range of household needs and wants:', ARRAY['Households need food, shelter, and medical care to maintain basic well-being.', 'Sports, cinema visits, and café outings are examples of wants rather than strict needs.', 'A household buying cinema tickets is satisfying a want through exchange with a business.', 'Households and entrepreneurs interact when families purchase goods and services from firms.', 'Limited household income forces economising between essential needs and discretionary wants.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Basic nutrition, housing, and healthcare are core examples of household needs.', 'TRUE — Leisure and dining out are desired but not essential and are classified as wants.', 'TRUE — Paying for entertainment is monetary exchange fulfilling a want.', 'TRUE — Purchases from firms are the standard household–entrepreneur interaction.', 'TRUE — Finite income requires prioritising among needs and wants.'], '2/5', 29, 'full' ),
( '2.1', 'CASE 2.1.30', 'Cerny family September budget', 'The Cerny family has 1,400 euros after rent for groceries, school supplies, and an optional weekend trip. Evaluate:', ARRAY['Groceries and school supplies are needs, while the weekend trip is a want.', 'The fixed 1,400-euro remainder is a limited resource the household must economise.', 'School supplies bought for children count as needs of the household as a whole.', 'Deciding whether to book the trip is an economic decision because inaction is also a choice.', 'If the family skips the trip, their want for it is permanently erased and can never return.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Essentials for living and schooling are needs; a leisure trip is a non-essential want.', 'TRUE — A fixed budget is scarce relative to everything the family might like to fund.', 'TRUE — The household is the relevant unit; supplies for children are household needs.', 'TRUE — Postponing or rejecting the trip still allocates the scarce budget and counts as a decision.', 'FALSE — An unmet want may persist; skipping this month does not erase future desire for the trip.'], '3/5', 30, 'full' ),
( '2.2', 'CASE 2.2.01', 'Misunderstanding opportunity cost', 'Robin claims opportunity cost is the sum of every rejected option''s price. Sara chooses a 500-euro washer or 700-euro laptop. Evaluate:', ARRAY['If Sara buys the laptop, opportunity cost is the washer''s benefit forgone, not all rejected purchases combined.', 'Robin''s sum-of-all-rejected definition matches the standard economic definition exactly.', 'Choosing between only two items involves no scarcity because scarcity requires many options.', 'If Sara buys the washer, opportunity cost is 1,200 euros, the combined price of both items.', 'Opportunity cost refers to the alternative forgone, not the price of the item actually purchased.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Opportunity cost is the single next-best alternative''s benefit, here the washer.', 'FALSE — Standard definition uses the next-best alternative only, not a sum of all rejections.', 'FALSE — Scarcity applies whenever a limited budget must split between competing uses, even with two options.', 'FALSE — Opportunity cost of the washer is the 700-euro laptop benefit forgone, not 1,200 euros combined.', 'TRUE — It measures what is given up, not what is bought.'], '4/5', 1, 'full' ),
( '2.2', 'CASE 2.2.02', 'Bergmann renovation savings', 'The Bergmanns saved 18,000 euros for a full kitchen or full bathroom renovation, affordable only one this year. Evaluate:', ARRAY['18,000 euros is a limited resource allocated between kitchen and bathroom projects.', 'Kitchen renovation means opportunity cost is the bathroom renovation''s benefit forgone.', 'Bathroom renovation means opportunity cost is greater resale value forgone from the kitchen.', 'Identical 18,000-euro costs mean neither option can have opportunity cost.', 'As a household, the Bergmanns face the same allocation problem as firms and governments.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Fixed savings force a choice between two renovations.', 'TRUE — The bathroom benefit is forgone when the kitchen is chosen.', 'TRUE — The kitchen''s higher resale benefit is forgone when the bathroom is chosen.', 'FALSE — Equal prices do not remove forgone benefits of the unchosen project.', 'TRUE — Household renovation budgets illustrate universal scarce-resource trade-offs.'], '2/5', 2, 'full' ),
( '2.2', 'CASE 2.2.03', 'Simon: car wash or volunteering', 'Simon can earn 45 euros at a car wash or volunteer at an animal shelter on the same Saturday. Evaluate opportunity cost:', ARRAY['If Simon volunteers, the opportunity cost is the 45 euros forgone from the car wash shift.', 'Scarcity concerns only money, so Simon faces no real scarcity when choosing how to use his Saturday.', 'Personal satisfaction from volunteering cancels any opportunity cost that might otherwise exist.', 'Because Simon is a teenager, scarce-resource allocation concepts do not apply to his Saturday.', 'The shelter''s dog food cost is part of Simon''s opportunity cost when he chooses volunteering.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Opportunity cost is the benefit of the next-best alternative forgone: the 45-euro wage.', 'FALSE — Time is a scarce resource even when pay differs; Saturday hours cannot be used for both activities.', 'FALSE — Satisfaction does not eliminate opportunity cost; the forgone wage still counts.', 'FALSE — Individuals allocate scarce time regardless of age or employment status.', 'FALSE — Opportunity cost is what Simon personally gives up, not a third party''s unrelated expenses.'], '3/5', 3, 'full' ),
( '2.2', 'CASE 2.2.04', 'Three actors, one week', 'The Webers choose holiday versus loan repayment; a firm chooses hire versus vans; a ministry chooses motorway versus railway. Evaluate:', ARRAY['Households, firms, and governments all allocate fixed budgets among competing uses this year.', 'The holiday''s opportunity cost is the benefit of early loan repayment the Webers give up.', 'Hiring a sales rep means giving up the benefit of upgrading delivery vans instead.', 'Resurfacing the motorway means giving up the railway extension''s benefit for residents.', 'A teenager''s Saturday hours spent studying forfeit paid work income as opportunity cost.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — All three actors face limited funds and must choose among alternatives.', 'TRUE — Forgoing early repayment is the next-best alternative to taking the holiday.', 'TRUE — The van upgrade benefit is forgone when the hire is chosen.', 'TRUE — The railway benefit is the opportunity cost of choosing the motorway.', 'TRUE — Forgone wage from the job alternative is the financial opportunity cost of studying.'], '3/5', 4, 'full' ),
( '2.2', 'CASE 2.2.05', 'Elif: tutoring or unpaid internship', 'Elif can keep tutoring for 400 euros monthly or take an overlapping unpaid architecture internship. Evaluate:', ARRAY['Accepting the internship means opportunity cost is 400 euros monthly tutoring income forgone.', 'Because the internship pays nothing, choosing it has no opportunity cost at all.', 'Keeping tutoring means giving up career experience and prospects from the internship.', 'Opportunity cost must always be expressed only in euros with no other dimensions allowed.', 'Elif still allocates scarce time between tutoring and internship despite being a student.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Forgone tutoring income is the financial benefit of the next-best alternative.', 'FALSE — Zero internship pay does not remove forgone tutoring wages as opportunity cost.', 'TRUE — Staying in tutoring forgoes internship experience, the next-best alternative''s benefit.', 'FALSE — Non-financial benefits may matter, but forgone income still defines core opportunity cost.', 'TRUE — Student status does not exempt individuals from scarce time allocation.'], '3/5', 5, 'full' ),
( '2.2', 'CASE 2.2.06', 'Ana: bakery job or market stall', 'Ana earns 1,900 euros monthly at a supermarket bakery or could run a stall earning 2,100 euros without job security. Evaluate:', ARRAY['Opportunity cost equals the sum of every rejected alternative''s price added together.', 'Because the stall pays more, Ana''s decision to leave carries zero opportunity cost.', 'If Ana stays, the opportunity cost is the 2,100 euros she could have earned from the stall.', 'Choosing between two jobs involves no scarcity because she selects between jobs rather than physical goods.', 'Paid holidays cannot factor into opportunity cost because only euro amounts count.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — Only the single next-best forgone alternative defines opportunity cost, not all rejections combined.', 'FALSE — Every choice between competing uses of time has an opportunity cost regardless of expected gain.', 'TRUE — Staying means giving up the stall''s potential 2,100-euro income, the next-best alternative.', 'FALSE — Labour time is a scarce resource; job choice is a classic allocation problem.', 'FALSE — Non-financial factors may influence decisions, but forgone salary still defines core opportunity cost.'], '3/5', 6, 'full' ),
( '2.2', 'CASE 2.2.07', 'Nina: agency or freelance', 'Nina earns 2,700 euros at a design agency or could freelance for 3,100 euros with self-managed admin. Evaluate:', ARRAY['Freelancing means opportunity cost is 2,700-euro agency salary forgone.', 'Higher freelance pay eliminates opportunity cost from Nina''s decision entirely.', 'Staying at the agency means opportunity cost is potential 3,100-euro freelance income forgone.', 'Admin work should be added directly onto salary to calculate opportunity cost by definition.', 'Working time is limited, so Nina''s choice reflects scarce-resource allocation.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Forgone agency salary is the next-best alternative when freelancing.', 'FALSE — Higher expected income does not erase forgone salary as opportunity cost.', 'TRUE — Forgone freelance income is the next-best alternative when staying employed.', 'FALSE — Opportunity cost is the alternative''s benefit, not salary plus administrative burden arithmetic.', 'TRUE — One career path at a time reflects scarce labour time.'], '3/5', 7, 'full' ),
( '2.2', 'CASE 2.2.08', 'Almeida garden plot', 'The Almeidas have forty square metres for vegetables saving 250 euros yearly or flowers they enjoy with no savings. Evaluate:', ARRAY['Forty square metres is a limited resource allocated between vegetables and flowers.', 'Choosing flowers means opportunity cost is roughly 250 euros annual grocery savings forgone.', 'Choosing vegetables means giving up enjoyment of a flower garden even if that benefit is non-financial.', 'Allocating overtime hours to maintenance forgoes backlog revenue that those hours could have earned.', 'The household faces the same allocation problem as firms and governments with scarce resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Fixed garden space is scarce and must be split between uses.', 'TRUE — Forgone grocery savings are the financial benefit of the next-best alternative.', 'TRUE — Forgone garden enjoyment is the benefit given up when vegetables are chosen.', 'TRUE — Forgone backlog revenue is the opportunity cost of choosing maintenance instead.', 'TRUE — Households face scarce-resource trade-offs like other economic actors.'], '3/5', 8, 'full' ),
( '2.2', 'CASE 2.2.09', 'City hall transport budget', 'City hall has 500,000 euros for a new bus line or protected bike lanes, insufficient for both fully this year. Evaluate:', ARRAY['The government must allocate its limited 500,000-euro budget between two transport projects.', 'Public projects funded by tax face no opportunity cost because they are not market-priced.', 'Because both projects improve transport, they cannot be compared using opportunity cost at all.', 'Choosing bike lanes means opportunity cost is the bus line''s benefit for commuters forgone.', 'Governments are exempt from the basic scarce-resources problem that households and firms face.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — A fixed capital budget split between projects is scarce-resource allocation.', 'FALSE — Tax funding does not remove forgone benefits of the unchosen project.', 'FALSE — Opportunity cost compares alternative uses of the same limited budget.', 'TRUE — The bus line benefit is the next-best alternative when bike lanes are built.', 'FALSE — Governments allocate limited budgets among competing uses like other actors.'], '2/5', 9, 'full' ),
( '2.2', 'CASE 2.2.10', 'Mila: bookstore or swimming academy', 'Mila can earn 60 euros at a bookstore or attend a free academy that might help a sports scholarship. Evaluate:', ARRAY['Saturday morning hours are scarce between the bookstore job and the academy.', 'Choosing the academy means opportunity cost is 60 euros bookstore earnings forgone.', 'Choosing the job means opportunity cost is training time and potential scholarship benefit forgone.', 'Uncertain scholarship benefit cannot count as any kind of opportunity cost.', 'Individuals face scarce-resource allocation, not only firms and governments.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Same hours cannot fully serve both activities.', 'TRUE — Forgone 60-euro wage is the financial next-best alternative.', 'TRUE — Forgone training and scholarship prospects are the next-best alternative when working.', 'FALSE — Uncertain benefits can still represent forgone alternatives in opportunity-cost reasoning.', 'TRUE — Students allocate scarce time like other decision-makers.'], '3/5', 10, 'full' ),
( '2.2', 'CASE 2.2.11', 'Factory overtime hours', 'A plant manager can assign limited overtime either to catch up order backlog or to preventive maintenance on Line 2. Evaluate:', ARRAY['Overtime hours are scarce and allocated between backlog clearance and maintenance.', 'Backlog overtime means opportunity cost is reduced breakdown risk benefit from maintenance forgone.', 'Maintenance overtime means opportunity cost is delayed-shipment revenue from backlog work forgone.', 'Overtime is unlimited if workers agree, so no allocation problem exists.', 'Opportunity cost helps compare competing uses of the same limited hour pool.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Finite overtime slots create competing uses.', 'TRUE — Maintenance risk reduction is forgone when backlog gets the hours.', 'TRUE — Backlog revenue is forgone when maintenance gets the hours.', 'FALSE — Legal, fatigue, and budget caps still limit usable overtime.', 'TRUE — Same hour pool, different benefits: classic opportunity cost framing.'], '3/5', 11, 'full' ),
( '2.2', 'CASE 2.2.12', 'Irrigation water: wheat or vegetables', 'Farmer Ilić can fully irrigate wheat (12,000-euro revenue) or vegetables (15,500-euro revenue) this month, not both. Evaluate:', ARRAY['Limited irrigation water is scarce and must be allocated between the two field types.', 'Irrigating vegetables means opportunity cost is 27,500 euros, the combined revenue of both fields.', 'Because Ilić is a farmer not a registered firm, his decisions involve no opportunity cost.', 'Irrigating wheat means opportunity cost is 15,500 euros vegetable revenue forgone.', 'Same-farm fields mean watering one does not count as allocating a scarce resource.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — Fixed water supply this month is the scarce resource.', 'FALSE — Opportunity cost is the wheat revenue forgone (12,000), not combined totals.', 'FALSE — Any decision-maker allocating scarce resources faces opportunity cost.', 'TRUE — Wheat choice forgoes 15,500-euro vegetable revenue, the next-best alternative.', 'FALSE — Limited water on one farm still requires allocation between uses.'], '3/5', 12, 'full' ),
( '2.2', 'CASE 2.2.13', 'Bergdorf council budget', 'Bergdorf has 90,000 euros for either a skate park or a library renovation this year, not both. Evaluate:', ARRAY['Scarcity applies only to money, never to time, land, or labour hours.', 'Households never face opportunity cost because wants are unlimited and budgets do not constrain them.', 'Because councils can raise taxes in principle, this year''s 90,000-euro budget is not scarce.', 'Opportunity cost exists only for registered companies, not for individuals or students.', 'Choosing the library means opportunity cost is the skate park''s benefit, not both projects combined.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Time, land, and labour are classic scarce resources requiring allocation.', 'FALSE — Limited budgets force households to give up some alternatives when choosing others.', 'FALSE — Within this year the 90,000-euro envelope is fixed and therefore scarce.', 'FALSE — Individuals allocating scarce time or money face opportunity cost like firms and governments.', 'TRUE — Opportunity cost is one alternative''s benefit, not the sum of all rejected options.'], '2/5', 13, 'full' ),
( '2.2', 'CASE 2.2.14', 'Retail chain store location', 'A chain can open one store: location A projects 220,000-euro profit, location B 180,000-euro profit. Evaluate:', ARRAY['Available capital this year is scarce and allocated between location A and B.', 'Opening at A means opportunity cost is 180,000-euro profit from B forgone.', 'Opening at B means opportunity cost is 400,000 euros, combined profit of both locations.', 'Large firms'' expansion decisions never involve scarce resources because of their size.', 'This illustrates firms allocating limited resources among competing uses like households do.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — One-store capital limit creates scarcity between sites.', 'TRUE — Location B profit is the next-best alternative when A opens.', 'FALSE — Opportunity cost of B is 220,000-euro A profit forgone, not combined totals.', 'FALSE — Even large firms have finite capital per period for expansion.', 'TRUE — Capital allocation among projects is the basic economic problem for firms.'], '3/5', 14, 'full' ),
( '2.2', 'CASE 2.2.15', 'Mateo: salary versus freelancing', 'Mateo earns 3,600 euros monthly salaried or could freelance for 4,200 euros without employer health insurance. Evaluate:', ARRAY['Mateo allocates limited working time between two competing income paths.', 'Taking freelance means giving up 3,600-euro salary and employer-paid benefits as opportunity cost.', 'Staying salaried means giving up potential 4,200-euro freelance income as opportunity cost.', 'Because he cannot do both full-time, working hours are a scarce resource forcing one choice.', 'Opportunity cost as the next-best alternative''s benefit applies directly to Mateo''s decision.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — One person cannot fully pursue two full-time paths simultaneously.', 'TRUE — Forgone salary and benefits are the next-best alternative when freelancing is chosen.', 'TRUE — Forgone freelance income is the next-best alternative when staying salaried.', 'TRUE — Limited hours create the scarcity that makes opportunity cost meaningful.', 'TRUE — This matches the definition: benefit of the next-best alternative given up.'], '2/5', 15, 'full' ),
( '2.2', 'CASE 2.2.16', 'Ministry vaccine vans', 'A health ministry can fund mobile vaccine vans or clinic refrigeration upgrades this fiscal year, not both fully. Evaluate:', ARRAY['The ministry allocates a fixed health budget between vans and refrigeration upgrades.', 'Choosing vans means opportunity cost is clinic refrigeration benefits forgone in underserved districts.', 'Public health spending faces no opportunity cost because saving lives overrides all budget limits.', 'Governments choose among projects without giving up any benefit from rejected alternatives.', 'Limited fiscal-year funding makes the budget a scarce resource requiring a choice.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — Governments split limited health budgets among competing programmes.', 'TRUE — Refrigeration benefits are the next-best alternative when vans are funded.', 'FALSE — Even life-saving budgets force trade-offs between competing health investments.', 'FALSE — Rejected projects'' benefits remain the opportunity cost of the chosen one.', 'TRUE — Annual caps create scarcity within the budget cycle.'], '3/5', 16, 'full' ),
( '2.2', 'CASE 2.2.17', 'Petr''s bike shop Saturday', 'Petr alone on Saturdays earns 380 euros on repairs or 460 euros on sales, but cannot do both fully. Evaluate:', ARRAY['Saturday hours are a scarce resource split between repairs and sales.', 'A repair day means opportunity cost is 460 euros forgone from focusing on sales.', 'A sales day means opportunity cost is 380 euros forgone from repairs.', 'Inability to do both fully illustrates allocating scarce resources among competing uses.', 'Opportunity cost as next-best alternative benefit determines Petr''s cost in either direction.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Limited hours force a choice between repair and sales focus.', 'TRUE — Repairs forgo the 460-euro sales outcome, the next-best alternative.', 'TRUE — Sales forgo the 380-euro repair outcome, the next-best alternative.', 'TRUE — One person, one day, two uses: classic scarcity.', 'TRUE — Each choice gives up the other activity''s financial benefit.'], '2/5', 17, 'full' ),
( '2.2', 'CASE 2.2.18', 'Startup hire decision', 'A startup can afford one hire: a developer speeding product work or a marketer boosting sales. Evaluate:', ARRAY['The hiring budget is scarce and allocated between developer and marketer roles.', 'Hiring the developer means opportunity cost is the developer''s own annual salary figure.', 'New startups are exempt from scarce-resource problems that apply to established firms.', 'Hiring the marketer means opportunity cost is the benefit forgone from hiring the developer.', 'Similar salaries mean this decision involves no meaningful opportunity cost either way.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — Limited funding forces one role this quarter.', 'FALSE — Opportunity cost is the marketer''s benefit forgone, not the developer''s salary paid.', 'FALSE — Startups face the same allocation constraints as older firms.', 'TRUE — The developer''s contribution is the next-best alternative when the marketer is hired.', 'FALSE — Similar pay does not eliminate forgone benefits of the unchosen role.'], '3/5', 18, 'full' ),
( '2.2', 'CASE 2.2.19', 'Community grant committee', 'A town trust grants 25,000 euros to either a youth music programme or a seniors'' digital literacy class. Evaluate:', ARRAY['The grant pool is a scarce resource split between two community programmes.', 'Music funding means opportunity cost is literacy-class benefits forgone for seniors.', 'Non-profit grants face no opportunity cost because donations are not market transactions.', 'Literacy funding means opportunity cost is music-programme benefits forgone for youth.', 'Committees allocate limited philanthropic funds among competing worthy causes.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — One grant amount cannot fully fund both programmes.', 'TRUE — Literacy benefits are the next-best alternative when music is funded.', 'FALSE — Limited grant money still forces trade-offs between causes.', 'TRUE — Music benefits are the next-best alternative when literacy is funded.', 'TRUE — Philanthropic budgets illustrate scarce-resource allocation.'], '3/5', 19, 'full' ),
( '2.2', 'CASE 2.2.20', 'Handwerk GmbH timber choice', 'Handwerk GmbH can use its oak batch for dining tables (40,000-euro profit) or bookshelves (28,000-euro profit), not both. Evaluate:', ARRAY['Choosing the lower-return option means opportunity cost is zero because a better option existed.', 'Personal satisfaction from an activity eliminates any opportunity cost associated with it.', 'Economising means treating limited resources as if they were unlimited without any prioritisation.', 'Sharing the same timber means no opportunity cost exists because the wood is used either way.', 'Limited oak forces economising by selecting the more profitable product line.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — The better option''s benefit remains the opportunity cost of the lower-return choice.', 'FALSE — Non-monetary enjoyment does not remove forgone benefits of the unchosen alternative.', 'FALSE — Economising is careful use of scarce resources, the opposite of assuming unlimited supply.', 'FALSE — Shared limited timber is exactly why a choice and opportunity cost arise.', 'TRUE — Scarce timber requires choosing the higher-return allocation.'], '3/5', 20, 'full' ),
( '2.2', 'CASE 2.2.21', 'Scarcity recap lesson', 'A teacher compares household saving versus sofa, firm investment choice, and government infrastructure choice with fixed budgets. Evaluate:', ARRAY['In each case resources are limited relative to what the decision-maker would like to fund.', 'The basic problem is that households, firms, and governments allocate scarce resources among competing uses.', 'Opportunity cost of one option is the benefit of the next-best alternative given up.', 'Household sofa choice means opportunity cost is the benefit of money saved instead.', 'Government infrastructure choice means opportunity cost is the other project''s benefit forgone.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Limited budgets against multiple desires create the need to choose.', 'TRUE — This is the universal scarce-resources problem across actor types.', 'TRUE — Standard definition applies in all three examples.', 'TRUE — Forgone saving value is the next-best alternative to buying the sofa.', 'TRUE — The unchosen project''s benefit is the government''s opportunity cost.'], '2/5', 21, 'full' ),
( '2.2', 'CASE 2.2.22', 'Wealthy heir''s afternoon', 'David inherits wealth and chooses between a museum visit or lunch with a friend because events overlap. Evaluate:', ARRAY['Choosing the museum means giving up the benefit of lunch with his friend as opportunity cost.', 'Unlimited money makes David''s time unlimited, so no opportunity cost arises.', 'Opportunity cost applies only to people worried about running out of money, not wealthy individuals.', 'Because David is not a registered business, scarce resources and opportunity cost do not apply.', 'Because both activities cost similar amounts, this choice involves no real opportunity cost.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Overlapping events make time scarce; the forgone lunch is the next-best alternative.', 'FALSE — Unlimited cash does not make time unlimited.', 'FALSE — Time scarcity creates opportunity cost regardless of wealth.', 'FALSE — Personal afternoon choices involve scarce time for all individuals.', 'FALSE — Similar prices do not eliminate forgone benefits of the unchosen activity.'], '4/5', 22, 'full' ),
( '2.2', 'CASE 2.2.23', 'Chef''s evening service', 'Chef Lina can serve a sold-out tasting menu or a walk-in banquet for the same kitchen slot, not both. Evaluate:', ARRAY['One kitchen service window is a scarce resource between tasting menu and banquet.', 'Tasting menu means opportunity cost is banquet revenue and reputation benefit forgone.', 'Banquet means opportunity cost is tasting-menu margin and regular clientele goodwill forgone.', 'Restaurants with paying customers never economise because demand guarantees unlimited resources.', 'Lina must allocate limited prep time and stove capacity between the two events.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Same slot, two events: time and capacity are scarce.', 'TRUE — Banquet proceeds are the next-best alternative when tasting menu runs.', 'TRUE — Tasting margin is the next-best alternative when banquet is chosen.', 'FALSE — Kitchen labour and capacity remain limited even with strong demand.', 'TRUE — Prep time and equipment are scarce inputs requiring economising.'], '2/5', 23, 'full' ),
( '2.2', 'CASE 2.2.24', 'Warehouse shift allocation', 'A logistics firm assigns one forklift crew Saturday to either clearing backlogged imports or reorganising the outbound bay. Evaluate:', ARRAY['One crew on one Saturday is a scarce resource allocated between two tasks.', 'Choosing imports means opportunity cost is the outbound reorganisation benefit forgone.', 'Because both tasks occur in the same warehouse, no scarce resource is involved.', 'Firms never face opportunity cost for internal tasks because all work uses the same building.', 'Opportunity cost equals the salary paid to the crew for whichever task they perform.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Limited crew hours force prioritisation between tasks.', 'TRUE — The reorganisation benefit is the next-best alternative when imports are cleared.', 'FALSE — Shared location does not make labour unlimited.', 'FALSE — Internal tasks compete for the same scarce labour hours.', 'FALSE — Opportunity cost is the other task''s benefit, not the crew''s wage bill.'], '3/5', 24, 'full' ),
( '2.2', 'CASE 2.2.25', 'Student laptop versus textbooks', 'Leo has 400 euros for either a refurbished laptop or a full semester textbook set, not both. Evaluate:', ARRAY['400 euros is a scarce student budget allocated between laptop and textbooks.', 'Buying the laptop means opportunity cost is study benefit forgone from owning the textbook set.', 'Buying textbooks means opportunity cost is productivity benefit forgone from the laptop.', 'Students are excluded from opportunity cost because education should be free of trade-offs.', 'Opportunity cost requires at least three alternatives; two options are insufficient.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Fixed student funds force a binary allocation choice.', 'TRUE — Forgone textbook access is the next-best alternative when the laptop is bought.', 'TRUE — Forgone laptop productivity is the next-best alternative when textbooks are bought.', 'FALSE — Students routinely face budget trade-offs like any household.', 'FALSE — Two alternatives are enough for opportunity cost to apply.'], '2/5', 25, 'full' ),
( '2.2', 'CASE 2.2.26', 'Opportunity cost direction', 'Evaluate precise claims about which alternative defines opportunity cost:', ARRAY['Opportunity cost always refers to the next-best alternative not chosen, not all rejected options combined.', 'Opportunity cost is identical for both sides of a trade because both parties give something up.', 'If no measurable financial benefit exists, opportunity cost is always zero by definition.', 'Choosing the lower-return option means opportunity cost is zero because the better option was available.', 'Households, firms, and governments all face opportunity cost when allocating scarce resources.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Only the single highest-value forgone alternative counts.', 'FALSE — Each party''s next-best alternative differs; the concept is not automatically symmetric in amount.', 'FALSE — Non-financial benefits can still represent forgone alternatives.', 'FALSE — Choosing lower return still forgoes the higher-return alternative as opportunity cost.', 'TRUE — Universal application across actor types is standard.'], '4/5', 26, 'full' ),
( '2.2', 'CASE 2.2.27', 'Time versus money trap', 'Evaluate whether opportunity cost applies only to financial decisions:', ARRAY['Choosing a free concert over paid overtime forfeits wage income as opportunity cost.', 'Opportunity cost applies only when both alternatives have explicit price tags attached.', 'Leisure time spent volunteering forfeits paid work hours that could have been chosen instead.', 'Non-financial enjoyment never enters opportunity-cost reasoning under any circumstances.', 'Scarce time creates opportunity cost even when the chosen activity has zero monetary price.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Forgone overtime wages are the next-best alternative when the free concert is chosen.', 'FALSE — Time and non-monetary benefits also define forgone alternatives.', 'TRUE — Volunteer hours could have been sold as paid labour instead.', 'FALSE — Enjoyment and experience can be part of what is given up or gained.', 'TRUE — Zero price does not mean zero opportunity cost when time is scarce.'], '3/5', 27, 'full' ),
( '2.2', 'CASE 2.2.28', 'Scarcity ''only for governments''?', 'Tobias claims scarce resources matter only for governments managing huge budgets. Evaluate:', ARRAY['A family choosing debt repayment versus a home extension faces the same allocation problem as government, smaller scale.', 'Scarcity affects only governments, never households or firms, by definition.', 'Smaller money amounts mean families face no genuine opportunity cost in their decisions.', 'Debt repayment opportunity cost exists only if the family is also a registered business.', 'Only decisions involving millions of people can be analysed with opportunity cost.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Households face scarce budgets and forgone alternatives just like governments.', 'FALSE — Scarcity applies to households and firms as well as governments.', 'FALSE — Opportunity cost depends on alternatives forgone, not on budget size alone.', 'FALSE — Household financial choices carry opportunity cost without business registration.', 'FALSE — Opportunity cost applies at any scale where resources are limited.'], '4/5', 28, 'full' ),
( '2.2', 'CASE 2.2.29', 'Universal allocation principle', 'Assess the basic economic problem across actors and resources:', ARRAY['Limited resources relative to wants force households, firms, and governments to make choices.', 'Allocation means deciding how to distribute scarce resources among competing uses.', 'Opportunity cost is the benefit of the next-best alternative given up when one option is chosen.', 'Economising is necessary whenever resources are scarce rather than unlimited.', 'The same logic applies whether the scarce resource is money, land, labour hours, or hospital beds.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Universal scarcity creates choices for all actor types.', 'TRUE — Allocation is the act of distributing limited resources among alternatives.', 'TRUE — Standard definition of opportunity cost across contexts.', 'TRUE — Economising responds to scarcity for any resource type.', 'TRUE — Scarcity is resource-general, not limited to cash budgets.'], '2/5', 29, 'full' ),
( '2.2', 'CASE 2.2.30', 'Hospital bed allocation', 'A ward has one ICU bed left for either a scheduled surgery patient or an emergency admission arriving tonight. Evaluate:', ARRAY['The last ICU bed is a scarce resource allocated between scheduled and emergency use.', 'Assigning emergency means opportunity cost is scheduled surgery health benefit forgone.', 'Assigning scheduled means opportunity cost is emergency patient''s treatment benefit forgone.', 'Healthcare rationing never involves opportunity cost because medical ethics override economics.', 'Even non-monetary life-saving benefits can represent opportunity cost between patients.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — One bed, two patients: scarce medical capacity.', 'TRUE — Scheduled surgery benefit is forgone when emergency gets the bed.', 'TRUE — Emergency treatment benefit is forgone when scheduled patient gets the bed.', 'FALSE — Limited beds force trade-offs even in healthcare settings.', 'TRUE — Forgone treatment outcomes can define opportunity cost without euro pricing.'], '4/5', 30, 'full' ),
( '2.3', 'CASE 2.3.01', 'Household heating bill', 'The Weiss family compares gas versus heat-pump suppliers for next winter''s contract, ignoring national energy policy. Evaluate:', ARRAY['Macroeconomics cannot explain recessions because only micro markets exist.', 'Energy is always macroeconomics because heating affects national consumption statistics.', 'If policymakers analysed total household energy use affecting national inflation, that would be macroeconomics.', 'Economics studies such household trade-offs under a limited monthly budget.', 'Micro and macro ask identical questions, so analysing the Weiss family equals analysing the nation.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Macro theories explicitly address economy-wide downturns and aggregates.', 'FALSE — Topic area alone does not determine classification; level of analysis does.', 'TRUE — Aggregated energy use impacting inflation shifts to macro.', 'TRUE — Budget-limited household choice is core micro subject matter.', 'FALSE — Scope differs: one household versus entire economy.'], '3/5', 1, 'full' ),
( '2.3', 'CASE 2.3.02', 'Export statistics release', 'The trade ministry publishes total national exports and imports for the year. Evaluate:', ARRAY['Whole-country export and import totals are macroeconomic statistics.', 'One exporting winery''s shipment schedule to Germany is macroeconomics because trade crosses a border.', 'Macro topics include growth, unemployment, inflation, and interest rates alongside aggregates like trade totals.', 'Economics tries to explain why national export performance changes over time.', 'Microeconomics studies individual firms'' export decisions when those firms are the unit analysed.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — National trade totals summarise the whole economy.', 'FALSE — One firm''s shipment schedule analysed alone is micro, despite international trade.', 'TRUE — Trade aggregates sit alongside other macro indicators.', 'TRUE — Explaining national export trends is macroeconomic analysis.', 'TRUE — Firm-level export choice is micro when scope is the individual business.'], '3/5', 2, 'full' ),
( '2.3', 'CASE 2.3.03', 'Fatima''s electric hatchback choice', 'Fatima compares buying an electric hatchback with a government bonus versus keeping her petrol car two more years. Evaluate micro versus macro:', ARRAY['Any price change anywhere is automatically macroeconomics regardless of scope analysed.', 'Because a national bonus programme exists, her purchase automatically becomes macroeconomics instead of micro.', 'Microeconomics and macroeconomics are unrelated subjects with no shared foundation (alt 2.3/2).', 'Nationwide statistics on total car sales after the bonus would be macroeconomic analysis.', 'Microeconomics and macroeconomics study identical questions with no meaningful scope difference.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Individual firm or product pricing analysed alone is micro; macro uses general price levels.', 'FALSE — Policy origin does not reclassify an individual choice; scope of analysis matters.', 'FALSE — Both branches study resource allocation and build explanatory theories at different scopes.', 'TRUE — Aggregated national sales and growth effects are macroeconomic.', 'FALSE — Micro focuses on individual units; macro on the whole economy.'], '3/5', 3, 'full' ),
( '2.3', 'CASE 2.3.04', 'Freonia quarterly report', 'Freonia''s statistics office reports national growth, unemployment, and central-bank interest rates each quarter. Evaluate:', ARRAY['This whole-economy report is macroeconomic analysis rather than a single unit''s decision.', 'Growth, unemployment, and interest rates are macroeconomic topics alongside inflation and price levels.', 'One bakery studying only its own sales and staffing would be microeconomics.', 'Economics as a science builds theories to explain and predict such nationwide phenomena.', 'Both branches fall under economics defined as decisions under limited resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Whole-economy indicators are macroeconomic by definition.', 'TRUE — These variables are standard macro topics listed alongside inflation.', 'TRUE — Single-firm operational analysis is microeconomic.', 'TRUE — Explaining and predicting aggregate outcomes is the scientific aim of economics.', 'TRUE — Micro and macro are branches of the same resource-allocation discipline.'], '2/5', 4, 'full' ),
( '2.3', 'CASE 2.3.05', 'Recession headline', 'Headlines report two consecutive quarters of falling national GDP and rising job losses economy-wide. Evaluate:', ARRAY['Falling national GDP and economy-wide job losses are macroeconomic phenomena.', 'One closed shop laying off two staff is macroeconomics because layoffs appear in the headline.', 'Macroeconomics aims to explain and predict recessions and recovery patterns.', 'Economics as a whole studies decisions under limited resources at micro and macro levels.', 'Microeconomics cannot study unemployment because unemployment exists only at macro level.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — National GDP decline and widespread job losses are macro aggregates.', 'FALSE — Two layoffs at one shop analysed alone is micro; macro uses economy-wide totals.', 'TRUE — Recession explanation and prediction are macroeconomic theory tasks.', 'TRUE — Both branches share the limited-resources foundation.', 'FALSE — Micro studies unemployment risk and hiring at firm and household level too.'], '4/5', 5, 'full' ),
( '2.3', 'CASE 2.3.06', 'BrewPeak espresso price hike', 'Inês raises BrewPeak espresso prices after imported bean costs rise, thinking only about her Porto shop. Evaluate:', ARRAY['Economics fails as a science because human behaviour can never be studied with theories (alt 2.3/9).', 'Macroeconomics is simply the study of any price change, including one café''s espresso price.', 'Household budget choices are excluded from economics because only businesses matter (alt 2.3/10).', 'Macroeconomics cannot explain recessions because only micro markets exist (alt 2.3/11).', 'Economics remains a science building theories to explain and predict behaviour despite imperfect human prediction.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Economics builds theories to explain and predict behaviour despite imperfect foresight.', 'FALSE — Macro studies economy-wide price levels, not every individual firm''s price.', 'FALSE — Household decisions under scarcity are central to economics, especially microeconomics.', 'FALSE — Macro theories explicitly address economy-wide downturns and aggregates.', 'TRUE — Theory-building for explanation and prediction defines economics as a science.'], '4/5', 6, 'full' ),
( '2.3', 'CASE 2.3.07', 'Ride-hail surge pricing', 'One ride-hail platform raises fares in one city district after a concert ends. Evaluate:', ARRAY['Studying surge pricing for one platform in one district is microeconomics.', 'Surge pricing is macroeconomics because many riders are affected at once.', 'If analysts measured whether district fare spikes raised the city''s overall consumer price index, that index move would be macroeconomics.', 'Economics can predict how riders and drivers respond to a local price spike.', 'Individual market pricing never falls within economics because only governments set prices.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Single-market, single-platform pricing is micro scope.', 'FALSE — Many participants do not automatically make analysis macro; aggregation level matters.', 'TRUE — General price index change is macro even if triggered by local surges.', 'TRUE — Local behavioural response prediction is microeconomic theory application.', 'FALSE — Market pricing by firms is central microeconomic subject matter.'], '3/5', 7, 'full' ),
( '2.3', 'CASE 2.3.08', 'Micro scope traps', 'Evaluate fine-grained claims about what counts as microeconomics:', ARRAY['A single farmer choosing between wheat and vegetable crops on limited irrigation water is microeconomics.', 'A single bakery setting its loaf price after flour costs rise is microeconomics.', 'A city bus company setting a new single-route fare is microeconomics when only that firm''s pricing is analysed.', 'National GDP growth rate publication is macroeconomics because it summarises the entire economy.', 'Microeconomics can explain and predict behaviour of individual markets, households, and firms.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — One producer''s resource allocation is microeconomic analysis.', 'TRUE — One firm''s pricing decision examined alone is microeconomic analysis.', 'TRUE — Single-firm fare setting examined alone is micro.', 'TRUE — GDP growth is a whole-economy macro indicator.', 'TRUE — Micro builds theories to explain and predict individual-unit behaviour.'], '4/5', 8, 'full' ),
( '2.3', 'CASE 2.3.09', 'Confusing scope with topic', 'Students debate whether ''prices'' and ''jobs'' are always macro or micro topics. Evaluate:', ARRAY['Micro and macro study identical questions with no meaningful difference in scope.', 'Any discussion of wages is automatically macroeconomics because labour markets are national.', 'Economy-wide average wage growth published by a statistics office is macroeconomics.', 'A household choosing between two job offers compares micro-level alternatives under limited time.', 'Economics cannot explain individual choices, only nationwide aggregates.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Micro focuses on individual units; macro on economy-wide aggregates.', 'FALSE — Wages can be studied at firm level (micro) or economy level (macro).', 'TRUE — Average wage growth across the economy is a macro aggregate.', 'TRUE — Individual job choice among offers is micro household labour allocation.', 'FALSE — Economics explains and predicts both individual and aggregate outcomes.'], '4/5', 9, 'full' ),
( '2.3', 'CASE 2.3.10', 'Teacher''s scope quiz', 'A teacher lists examples and asks which are micro versus macro. Evaluate the classification rules:', ARRAY['Micro examines individual households, businesses, or markets; macro examines the whole economy.', 'A single consumer choosing organic milk is microeconomics.', 'National unemployment rate is macroeconomics.', 'Economics explains and predicts at both scopes using theories about limited resources.', 'If an example mentions government, it must always be classified as macroeconomics.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Unit versus whole-economy scope is the core distinction.', 'TRUE — One consumer''s product choice is micro.', 'TRUE — Economy-wide unemployment is macro.', 'TRUE — Explanation and prediction apply in both branches.', 'FALSE — Government can act at micro scope (one project) or macro scope (national policy).'], '2/5', 10, 'full' ),
( '2.3', 'CASE 2.3.11', 'Household savings rate national data', 'Central bank publishes average household savings rate across the entire country. Evaluate:', ARRAY['Average national household savings rate is a macroeconomic aggregate.', 'One family increasing its monthly savings by fifty euros is macroeconomics because saving is national policy topic.', 'Macro includes growth, unemployment, inflation, interest rates, and such economy-wide averages.', 'Economics explains and predicts how aggregate saving responds to interest rate changes.', 'Microeconomics studies one family''s saving choice when that family alone is the unit analysed.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Country-wide average saving is macro.', 'FALSE — One family''s fifty-euro change analysed alone is micro.', 'TRUE — Economy-wide averages alongside standard macro variables.', 'TRUE — Aggregate saving response to rates is macro prediction.', 'TRUE — Single-household saving decision is micro at unit scope.'], '3/5', 11, 'full' ),
( '2.3', 'CASE 2.3.12', 'Startup funding round', 'Ten startups in a city receive venture funding; an analyst studies only one robotics firm''s hiring plan. Evaluate:', ARRAY['Any price change anywhere is automatically macroeconomics regardless of scope analysed (alt 2.3/1).', 'Because venture capital is a national phenomenon, any firm-level study becomes macroeconomics.', 'Summing all startup investment in the country to assess economic growth would be macroeconomics.', 'Microeconomics explains and predicts behaviour of individual businesses and markets.', 'Economics excludes entrepreneurial firms because they are too small for scientific study.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Individual firm or product pricing analysed alone is micro; macro uses general price levels.', 'FALSE — National funding trends do not reclassify one-firm study as macro.', 'TRUE — Aggregating startup investment for growth analysis is macro.', 'TRUE — Individual business behaviour is micro''s explanatory target.', 'FALSE — Small firms and startups are standard microeconomic units.'], '3/5', 12, 'full' ),
( '2.3', 'CASE 2.3.13', 'Kelvinia rate rise', 'Kelvinia''s central bank raises the key interest rate nationwide to slow inflation. Evaluate:', ARRAY['Micro and macro study identical questions with no meaningful difference in scope (alt 2.3/12).', 'Any price change anywhere is automatically macroeconomics regardless of scope analysed (alt 2.3/13).', 'Microeconomics and macroeconomics are unrelated subjects with no shared foundation (alt 2.3/14).', 'Because mortgages of specific families change, the central-bank move is automatically microeconomics.', 'Economics tries to build theories explaining why central banks raise rates and predict inflation effects.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Micro focuses on individual units; macro on economy-wide aggregates.', 'FALSE — Individual firm or product pricing analysed alone is micro; macro uses general price levels.', 'FALSE — Both branches study resource allocation and build explanatory theories at different scopes.', 'FALSE — Individual effects do not reclassify a whole-economy policy as micro.', 'TRUE — Theory and prediction about policy effects is central to economics as a science.'], '3/5', 13, 'full' ),
( '2.3', 'CASE 2.3.14', 'Competition authority case', 'Regulators investigate whether three mobile carriers colluded on text-message pricing nationally. Evaluate:', ARRAY['Investigating pricing across an entire national mobile market can involve macro-style market-wide analysis.', 'One subscriber choosing a cheaper text plan for her own phone is microeconomics.', 'Economics builds theories to explain firm behaviour and market outcomes including competition issues.', 'Microeconomics studies individual firm pricing strategies when one carrier alone is analysed.', 'Economics excludes market competition because only government budgets matter.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Market-wide competition probes examine aggregate market structure, often treated at industry/macro-policy interface.', 'FALSE — One subscriber''s plan choice is clearly micro household decision-making.', 'TRUE — Firm behaviour and market outcomes are economic explanatory targets.', 'TRUE — Single-carrier pricing examined alone is micro.', 'FALSE — Market competition is core micro/industrial organisation subject matter.'], '4/5', 14, 'full' ),
( '2.3', 'CASE 2.3.15', 'Bookstore pricing experiment', 'A regional bookstore chain tests a 5% price cut in one city branch and tracks only that branch''s weekly revenue. Evaluate:', ARRAY['Analysing one branch''s revenue after its own price change is microeconomics.', 'Central bank inflation targeting for an entire currency area is macroeconomics.', 'If the national statistics office later reported economy-wide consumer price inflation, that would be macroeconomics.', 'Micro focuses on individual households, businesses, and markets rather than the whole economy.', 'Economics tries to explain and predict outcomes such as how a branch responds to a price cut.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Single-unit revenue response is microeconomic analysis.', 'TRUE — Economy-wide price stability policy is macro scope.', 'TRUE — General price level reporting is macro.', 'TRUE — Individual units versus whole economy defines the micro/macro split.', 'TRUE — Predicting branch-level response is microeconomic explanation.'], '2/5', 15, 'full' ),
( '2.3', 'CASE 2.3.16', 'Green subsidy household', 'A household buys solar panels after a national subsidy lowers the net price; analysts study only this family''s payback calculation. Evaluate:', ARRAY['One family''s payback calculation for its own panels is microeconomics.', 'Because a national subsidy exists, the family''s purchase cannot be microeconomics.', 'Measuring how the subsidy shifted total national renewable investment would be macroeconomics.', 'Economics studies household investment choices under limited budgets and expected savings.', 'Policy programmes eliminate the need for microeconomic analysis of individual buyers.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Single-household investment appraisal is micro.', 'FALSE — Policy backdrop does not change unit-level classification.', 'TRUE — Total national investment shift is macro aggregate analysis.', 'TRUE — Budget-limited household investment is micro subject matter.', 'FALSE — Individual buyer analysis remains micro even with subsidies.'], '3/5', 16, 'full' ),
( '2.3', 'CASE 2.3.17', 'National jobs report', 'A labour agency publishes economy-wide job creation and unemployment figures for the past year. Evaluate:', ARRAY['Economy-wide employment totals and unemployment rates are macroeconomic indicators.', 'Growth, unemployment, inflation, and interest rates are typical macroeconomic variables.', 'One restaurant deciding whether to extend opening hours is microeconomics when only that firm is studied.', 'Macro analysis can help explain why unemployment rises during a downturn.', 'Economics at macro level still concerns decisions and outcomes under limited economy-wide resources.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Aggregated labour-market statistics are macro.', 'TRUE — These are standard macro topics alongside growth and inflation.', 'TRUE — Single-firm hours decision analysed alone is micro.', 'TRUE — Explaining downturn unemployment is macroeconomic theory application.', 'TRUE — Aggregate constraints and outcomes remain within economics'' resource-allocation framework.'], '2/5', 17, 'full' ),
( '2.3', 'CASE 2.3.18', 'ECB inflation target discussion', 'Commentators discuss whether euro-area inflation at 2.3% requires tighter policy across the whole currency bloc. Evaluate:', ARRAY['Economics fails as a science because human behaviour can never be studied with theories (alt 2.3/3).', 'Inflation measurement for one grocery item in one shop is macroeconomics because inflation is involved.', 'A household reacting to higher bread prices by switching brands is microeconomics.', 'Macroeconomics tries to explain and predict economy-wide price level changes and policy responses.', 'Economics studies only macro aggregates and ignores individual household adjustments entirely.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Economics builds theories to explain and predict behaviour despite imperfect foresight.', 'FALSE — One product in one shop is micro even if prices rise; macro uses general price levels.', 'TRUE — One household''s brand switch under budget constraint is micro.', 'TRUE — Aggregate price dynamics and policy are macro explanatory targets.', 'FALSE — Household adjustments are micro and coexist with macro analysis.'], '3/5', 18, 'full' ),
( '2.3', 'CASE 2.3.19', 'Budget airline seat sale', 'A budget airline cuts base fares on one holiday route and tracks bookings for that route only. Evaluate:', ARRAY['Route-level fare and booking analysis for one airline is microeconomics.', 'Any airfare change is macroeconomics because airlines operate internationally.', 'Economics predicts how passengers on that route respond to the fare cut under limited budgets.', 'If the statistics office later reported national transport inflation, that would be macroeconomics.', 'Household holiday booking under a fare sale is micro consumption choice.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Single route, single firm demand response is micro.', 'FALSE — International operation does not make every fare decision macro.', 'TRUE — Passenger response prediction is micro behavioural analysis.', 'TRUE — National transport inflation index is macro.', 'TRUE — One household''s booking decision is micro.'], '2/5', 19, 'full' ),
( '2.3', 'CASE 2.3.20', 'Elif''s weekly work hours', 'Elif decides how many bookstore hours cover tuition, rent, and study time without analysing the national job market. Evaluate:', ARRAY['Microeconomics and macroeconomics are unrelated subjects with no shared foundation.', 'Because Elif is a student not a company, her situation falls outside economics entirely.', 'Household budget choices are excluded from economics because only businesses matter (alt 2.3/4).', 'Economics studies households deciding what to do with limited resources such as time and income.', 'Without a government bonus, Elif''s decision cannot be analysed using economic theory.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Both branches study resource allocation and build explanatory theories at different scopes.', 'FALSE — Household decisions are explicitly within economics'' scope.', 'FALSE — Household decisions under scarcity are central to economics, especially microeconomics.', 'TRUE — Limited resources and household choice are the core definition of economics.', 'FALSE — Ordinary household choices are standard economic analysis without special programmes.'], '2/5', 20, 'full' ),
( '2.3', 'CASE 2.3.21', 'Science of economics', 'Evaluate why economics is described as a science:', ARRAY['Economics builds theories to explain observed economic behaviour and outcomes.', 'Economics also uses theories to predict likely effects of choices and policies.', 'Reporting total national car sales after a subsidy programme is macroeconomic analysis.', 'Both micro and macro contribute explanatory and predictive theory at their respective scopes.', 'Limited resources forcing choices is the common foundation micro and macro share.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Theory-building for explanation is central to economics as a science.', 'TRUE — Prediction of policy and choice effects is part of its scientific method.', 'TRUE — Aggregated nationwide sales measure whole-economy outcomes, which is macro.', 'TRUE — Both branches develop testable theories at unit and aggregate levels.', 'TRUE — Scarcity and decision-making unify the discipline across branches.'], '2/5', 21, 'full' ),
( '2.3', 'CASE 2.3.22', 'Macro scope traps', 'Evaluate claims about macroeconomic topics and scope:', ARRAY['Economics fails as a science because human behaviour can never be studied with theories.', 'One shop hiring two extra cashiers is macroeconomics because employment is involved.', 'Micro and macro study identical questions with no meaningful difference in scope (alt 2.3/6).', 'Macroeconomics aims to explain and predict aggregate outcomes such as growth and price levels.', 'Economics is only macroeconomics; microeconomics is a separate subject unrelated to resource allocation.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Economics builds theories to explain and predict behaviour despite imperfect foresight.', 'FALSE — One firm''s hiring decision analysed alone is micro, not macro.', 'FALSE — Micro focuses on individual units; macro on economy-wide aggregates.', 'TRUE — Explanation and prediction of aggregates is macro''s scientific role.', 'FALSE — Micro and macro are branches of one discipline studying decisions under limited resources.'], '3/5', 22, 'full' ),
( '2.3', 'CASE 2.3.23', 'Branch distinction recap', 'Evaluate summary claims about micro versus macro:', ARRAY['Microeconomics focuses on individual households, firms, and markets.', 'Macroeconomics focuses on the whole economy including growth, unemployment, inflation, and interest rates.', 'Both branches study decisions under limited resources and aim to explain and predict outcomes.', 'Micro and macro are identical branches differing only in name with no scope distinction.', 'Classifying an example depends on whether the whole economy or a single unit is being analysed.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Individual units and markets define micro scope.', 'TRUE — Whole-economy aggregates define macro scope.', 'TRUE — Shared foundation and scientific aim across branches.', 'FALSE — Scope of analysis is the meaningful distinction.', 'TRUE — Unit versus whole economy is the classification rule.'], '2/5', 23, 'full' ),
( '2.3', 'CASE 2.3.24', 'Town housing permit', 'A municipality approves one apartment block''s building permit while ignoring national construction statistics. Evaluate:', ARRAY['Macroeconomics cannot explain recessions because only micro markets exist (alt 2.3/5).', 'All construction is macroeconomics because building affects national GDP automatically.', 'If analysts measured total national housing starts affecting growth, that would be macroeconomics.', 'Economics can study how limited land and budgets shape one municipality''s permit choice.', 'Households searching for flats never appear in microeconomics because housing is macro only.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Macro theories explicitly address economy-wide downturns and aggregates.', 'FALSE — GDP linkage does not reclassify every local permit decision as macro.', 'TRUE — National housing-start totals for growth are macro.', 'TRUE — Local scarce land and budget allocation is economic decision-making.', 'FALSE — Household flat search is classic micro consumption and housing choice.'], '3/5', 24, 'full' ),
( '2.3', 'CASE 2.3.25', 'Central bank press conference', 'The central bank governor discusses economy-wide inflation expectations and future interest-rate path for the currency area. Evaluate:', ARRAY['Economy-wide inflation expectations and rate path guidance are macroeconomic communication.', 'One shopkeeper raising coffee prices by ten cents is macroeconomics because coffee prices matter nationally.', 'Macroeconomics tries to explain and predict how aggregate demand and inflation interact.', 'Economics excludes monetary policy because money is not a limited resource.', 'A household deciding whether to fix its mortgage rate after the announcement is microeconomics.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Bloc-wide expectations and policy path are macro.', 'FALSE — One shop''s ten-cent change analysed alone is micro.', 'TRUE — Aggregate demand-inflation interaction is macro theory.', 'FALSE — Monetary policy addresses economy-wide resource allocation and price stability.', 'TRUE — One household''s mortgage choice is micro.'], '3/5', 25, 'full' ),
( '2.3', 'CASE 2.3.26', 'Pharmacy generic switch', 'One pharmacy switches a customer to a cheaper generic drug to save the household five euros monthly. Evaluate:', ARRAY['Any price change anywhere is automatically macroeconomics regardless of scope analysed (alt 2.3/7).', 'Any drug pricing discussion is macroeconomics because healthcare is a national sector.', 'If health authorities measured economy-wide pharmaceutical spending affecting budgets, that aggregate would be macroeconomics.', 'Economics studies how limited household income guides such product substitutions.', 'Micro and macro are unrelated fields studying completely different subject matter.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Individual firm or product pricing analysed alone is micro; macro uses general price levels.', 'FALSE — Sector size does not determine scope; unit of analysis does.', 'TRUE — Total pharmaceutical spending as an aggregate is macro.', 'TRUE — Budget-driven substitution is household decision-making under scarcity.', 'FALSE — Both branches study resource allocation at different levels.'], '2/5', 26, 'full' ),
( '2.3', 'CASE 2.3.27', 'Explain and predict mandate', 'Evaluate the scientific role of economics:', ARRAY['Economics builds theories to explain why economic outcomes occur.', 'Economics also uses theories to predict likely effects of decisions and policies.', 'Perfect foresight is required before any economic theory can be useful.', 'Micro theories predict individual market responses; macro theories predict aggregate trends.', 'Because humans behave unpredictably, economics cannot explain or predict anything scientifically.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Explanation of outcomes is a core scientific function.', 'TRUE — Prediction of policy and choice effects is equally central.', 'FALSE — Useful theories need not achieve perfect foresight.', 'TRUE — Both branches develop predictive theory at their scopes.', 'FALSE — Imperfect prediction still allows scientific explanation and useful forecasts.'], '3/5', 27, 'full' ),
( '2.3', 'CASE 2.3.28', 'Definition of economics', 'Evaluate core definitional claims about economics as a discipline:', ARRAY['Household budget choices are excluded from economics because only businesses matter.', 'Economics excludes household decisions and studies only corporate profit maximisation.', 'Microeconomics and macroeconomics are unrelated subjects with no shared foundation (alt 2.3/8).', 'Perfect prediction of human behaviour is required before economics can be called a science.', 'Microeconomics and macroeconomics are two branches applying the same core idea at different scopes.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Household decisions under scarcity are central to economics, especially microeconomics.', 'FALSE — Households are explicitly included, not excluded.', 'FALSE — Both branches study resource allocation and build explanatory theories at different scopes.', 'FALSE — Imperfect prediction does not disqualify economics; social sciences build useful theories despite uncertainty.', 'TRUE — Same resource-allocation logic at unit level (micro) versus aggregate level (macro).'], '2/5', 28, 'full' ),
( '2.3', 'CASE 2.3.29', 'Unified discipline', 'Assess how micro and macro fit together:', ARRAY['Economics studies decisions under limited resources made by households and businesses across the economy.', 'Microeconomics examines individual households, firms, and specific markets rather than the whole economy.', 'Macroeconomics examines whole-economy growth, unemployment, inflation, and interest rates at aggregate level.', 'Both micro and macro branches aim to explain and predict outcomes using built economic theories.', 'The same scarcity logic underlies choices studied at micro level and outcomes observed at macro level.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Core definition spans household and business decisions under constraint.', 'TRUE — Micro unit/market focus.', 'TRUE — Macro whole-economy indicators.', 'TRUE — Shared explanatory and predictive scientific aim.', 'TRUE — Scarcity connects individual choices to aggregate outcomes.'], '2/5', 29, 'full' ),
( '2.3', 'CASE 2.3.30', 'Mislabeled examples', 'Spot which scope label fits each example:', ARRAY['Reporting the national GDP growth rate for the whole country is macroeconomics, not a single firm''s decision.', 'One bakery hiring a part-time assistant to cover Saturday shifts is microeconomics when only that firm is studied.', 'Publishing the economy-wide unemployment rate across all regions is macroeconomics rather than one household''s choice.', 'One student choosing between two part-time job offers compares micro-level alternatives under limited time.', 'Any example involving money is automatically macroeconomics regardless of whether one unit or the whole economy is analysed.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — GDP is a whole-economy aggregate indicator and therefore macroeconomic.', 'TRUE — Single-firm hiring analysed alone is microeconomic scope.', 'TRUE — National unemployment is an economy-wide macro indicator.', 'TRUE — Individual job choice among offers is micro household labour allocation.', 'FALSE — Money appears in both micro and macro examples; scope of analysis determines classification, not currency alone.'], '4/5', 30, 'full' ),
( '2.4', 'CASE 2.4.01', 'Tax-funded lighthouse', 'A coastal town funds a lighthouse through general taxation rather than individual tolls. Evaluate:', ARRAY['Money''s store-of-value function is strengthened when inflation is very high and unpredictable.', 'Free riders would benefit from the beam without paying if funding relied purely on voluntary donations.', 'Tax financing can overcome free-rider problems by compelling contributions from beneficiaries broadly.', 'Because ships are private businesses, lighthouse services cannot be public goods by definition.', 'Public goods must always be provided free with zero cost to any taxpayer.'], ARRAY[false, true, true, false, false], ARRAY['FALSE — High inflation destroys real value stored in cash.', 'TRUE — Voluntary funding lets non-payers enjoy benefits without contributing.', 'TRUE — Taxation collects payment from the broader community benefiting from navigation safety.', 'FALSE — Public goods can benefit private users; excludability not user type defines the category.', 'FALSE — Public goods are funded collectively; they are not costless to society.'], '3/5', 1, 'full' ),
( '2.4', 'CASE 2.4.02', 'Saving euros under low inflation', 'A worker holds 1,000 euros in a current account while inflation runs slightly below 2%. Evaluate:', ARRAY['Money still stores value but slowly loses some purchasing power under positive inflation.', 'Slightly below 2% inflation means purchasing power rises every year for cash holders.', 'Store-of-value function is weaker when inflation is positive even if moderate.', 'ECB target near 2% contrasts with destabilising very high inflation rates.', 'Purchasing power of held cash depends on general price level changes domestically.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Moderate inflation erodes real value gradually.', 'FALSE — Positive inflation reduces real purchasing power over time.', 'TRUE — Cash loses real value unless nominal interest compensates inflation.', 'TRUE — Low stable target differs from harmful high inflation.', 'TRUE — Domestic prices determine real value of euro holdings locally.'], '3/5', 2, 'full' ),
( '2.4', 'CASE 2.4.03', 'Circular flow basics', 'Evaluate assertions about the circular flow of income and spending:', ARRAY['Stored cash never loses purchasing power because nominal euro amounts stay unchanged on the note.', 'Stored cash never loses purchasing power because nominal euro amounts stay unchanged on the note (alt 2.4/1).', 'Households can only appear on the spending side and never supply labour or capital to firms.', 'The circular flow shows how income earned from production returns as spending on output.', 'Government, banks, and foreign trade never appear in any circular-flow diagram.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Inflation reduces real value even when the printed number stays the same.', 'FALSE — Inflation reduces real value even when the printed number stays the same.', 'FALSE — Households supply factors of production, not only consumption demand.', 'TRUE — Earned income flows back as payment for goods and services produced.', 'FALSE — Extended diagrams include government, financial sector, and foreign trade links.'], '3/5', 3, 'full' ),
( '2.4', 'CASE 2.4.04', 'Hyperinflation pocket money', 'In a country with very rapid price rises, a child''s 20-euro note buys far less candy monthly. Evaluate:', ARRAY['Very rapid inflation sharply erodes purchasing power of nominally unchanged cash amounts.', 'Paying with a mobile transfer is exchange using money as medium of exchange.', 'Store-of-value function of money fails when inflation outpaces ability to spend or invest quickly.', 'ECB''s slightly-below-2% target aims at stability far from such hyperinflation scenarios.', 'Purchasing power erosion under inflation affects households as well as firms holding cash.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Fast price rises reduce real goods obtainable for fixed nominal money.', 'TRUE — Electronic payment is monetary exchange like cash.', 'TRUE — High inflation destroys real value stored in cash.', 'TRUE — ECB stability target contrasts with destabilising hyperinflation.', 'TRUE — Both households and firms lose real value on cash holdings when prices surge.'], '4/5', 4, 'full' ),
( '2.4', 'CASE 2.4.05', 'National park entry debate', 'Policals debate funding a national park via general tax versus gate fees only. Evaluate:', ARRAY['Clean air and preserved landscape benefits may extend beyond paying visitors, suggesting public-good elements.', 'Pure gate fees may exclude low-income residents while still leaving non-visitors benefiting from ecosystem services.', 'Tax funding can address free-rider issues when many benefit without direct payment.', 'National parks are never public goods because trees are physical objects you can touch.', 'Free-rider problems occur only in foreign trade and never in domestic environmental policy.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Ecosystem benefits can be non-excludable and widely shared.', 'TRUE — Excludable gate fees miss broader non-visitor benefits and access equity concerns.', 'TRUE — Taxation can fund shared benefits when voluntary payment would underfund upkeep.', 'FALSE — Public-good status depends on excludability and rivalry, not tangibility alone.', 'FALSE — Free-rider logic applies domestically to shared environmental benefits.'], '4/5', 5, 'full' ),
( '2.4', 'CASE 2.4.06', 'Money''s three functions', 'Analyze the three functions of money in a modern economy:', ARRAY['Inflation refers to one shop''s single price hike only, never to the general price level (alt 2.4/4).', 'Money''s store-of-value function is strengthened when inflation is very high and unpredictable (alt 2.4/5).', 'Only foreign trade creates free-rider problems; domestic public services never do (alt 2.4/6).', 'Because money stores value, its purchasing power never changes over time.', 'Barter requires a double coincidence of wants, which money helps overcome as medium of exchange.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Inflation is a general price-level phenomenon, not every individual price move.', 'FALSE — High inflation destroys real value stored in cash.', 'FALSE — Free-rider logic applies to domestic shared services such as parks and lighting.', 'FALSE — Inflation erodes purchasing power; stored money does not guarantee unchanged value.', 'TRUE — Barter needs matching wants; money simplifies exchange.'], '2/5', 6, 'full' ),
( '2.4', 'CASE 2.4.07', 'Circular flow with government', 'Evaluate government''s role in an extended circular flow:', ARRAY['Government collects taxes from households and firms and spends on public services and transfers.', 'Government spending and taxation appear in extended circular-flow models linking public sector to private actors.', 'Households never receive anything from government, so no return flow exists in the circular model.', 'Subsidies and transfers are channels through which government redistributes income in the flow.', 'The circular flow shows only barter with no role for money as medium of exchange.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Tax receipts and public expenditure connect government to households and firms.', 'TRUE — Extended diagrams include the public sector''s injections and withdrawals.', 'FALSE — Households receive transfers, public services, and sometimes employment income from government.', 'TRUE — Transfers and subsidies move purchasing power among actors in the flow.', 'FALSE — Modern circular-flow analysis assumes monetary exchange, not barter only.'], '3/5', 7, 'full' ),
( '2.4', 'CASE 2.4.08', 'Call centre task split', 'A support centre separates billing queries from technical troubleshooting across two teams. Evaluate:', ARRAY['Division of labour by query type lets agents specialise and often resolve cases faster.', 'Specialisation can reduce training time per agent for their assigned task category.', 'Households supply factors to firms and receive income that returns as spending in the circular flow.', 'If the billing team is understaffed, technical agents cannot cover without cross-training gaps.', 'Dependency between teams can create bottlenecks when one queue overflows.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Task-focused teams raise speed and expertise on repeated case types.', 'TRUE — Narrower training scope can shorten onboarding for each role.', 'TRUE — Factor payments and consumption close the basic income–spending loop.', 'TRUE — Lack of cross-skills limits flexibility during imbalances.', 'TRUE — Inter-team dependency mirrors manufacturing specialisation risks.'], '2/5', 8, 'full' ),
( '2.4', 'CASE 2.4.09', 'Subsidy for rail commuters', 'Government pays a per-trip subsidy lowering commuter rail tickets. Evaluate transfers and subsidies:', ARRAY['Inflation refers to one shop''s single price hike only, never to the general price level (alt 2.4/10).', 'Money''s store-of-value function is strengthened when inflation is very high and unpredictable (alt 2.4/11).', 'Subsidies are identical to public goods because both always require taxation.', 'Subsidised tickets can shift commuter choices toward rail without making rail a pure public good.', 'Transfers redistribute resources and can target policy goals such as mobility or environmental aims.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Inflation is a general price-level phenomenon, not every individual price move.', 'FALSE — High inflation destroys real value stored in cash.', 'FALSE — Subsidies support specific goods or groups; public goods are defined by non-excludability and shared benefit.', 'TRUE — Commuter rail remains a rival, excludable service even when subsidised.', 'TRUE — Transfers and subsidies pursue distributional or policy objectives.'], '2/5', 9, 'full' ),
( '2.4', 'CASE 2.4.10', 'Export subsidy debate', 'Government considers export subsidies for dairy cooperatives. Evaluate subsidies versus public goods:', ARRAY['Export subsidies transfer public funds to support a specific industry or activity.', 'Subsidies differ from pure public goods because subsidised goods remain excludable and rival in consumption.', 'All government spending is automatically a public good regardless of what is funded.', 'Subsidies can alter producer incentives and prices without making the product non-excludable.', 'Tax revenue funding subsidies links government to firms in the circular flow.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Subsidies target particular sectors with fiscal support.', 'TRUE — Subsidised dairy remains rival and excludable unlike defence or street lighting.', 'FALSE — Spending type determines public-good status, not government involvement alone.', 'TRUE — Subsidies shift costs and prices without changing excludability characteristics.', 'TRUE — Tax-funded subsidies connect public sector to producers in the flow model.'], '3/5', 10, 'full' ),
( '2.4', 'CASE 2.4.11', 'Barter weekend market', 'A hobby market allows only direct swaps: honey for bread, bread for pottery. Evaluate:', ARRAY['Barter requires double coincidence of wants between each pair of traders.', 'Absence of money as medium of exchange makes multilateral trading chains harder to arrange.', 'Such swaps still constitute exchange even when no currency is used.', 'Barter eliminates all comparison problems because traders always value goods equally.', 'Introducing money would add medium of exchange simplifying trades that barter complicates.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Each swap needs mutual want alignment at the same time.', 'TRUE — Without money, indirect exchange through many pairs is cumbersome.', 'TRUE — Barter remains exchange fulfilling wants without euros.', 'FALSE — Comparing unlike goods'' values is harder under barter without unit of account.', 'TRUE — Money''s medium-of-exchange role reduces matching friction.'], '4/5', 11, 'full' ),
( '2.4', 'CASE 2.4.12', 'Purchasing power over decades', 'A pensioner notes the same nominal 100 euros buys fewer groceries than thirty years ago. Evaluate:', ARRAY['Only foreign trade creates free-rider problems; domestic public services never do.', 'Nominal euro amounts automatically preserve real purchasing power regardless of price changes.', 'Money''s store-of-value function is weakened when inflation is positive over long periods.', 'Inflation slightly below 2% is the ECB''s stability target, not a mandate for ever-rising prices without limit.', 'Purchasing power depends only on foreign exchange rates and never on domestic price levels.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Free-rider logic applies to domestic shared services such as parks and lighting.', 'FALSE — Nominal amounts do not automatically maintain real buying power under inflation.', 'TRUE — Inflation reduces real value stored in cash over time.', 'TRUE — ECB targets inflation slightly below 2% for stability.', 'FALSE — Domestic price level chiefly determines domestic purchasing power of euro cash.'], '3/5', 12, 'full' ),
( '2.4', 'CASE 2.4.13', 'Inflation and purchasing power', 'Evaluate claims about inflation, purchasing power, and price stability:', ARRAY['Barter requires no matching of wants because any trade partners automatically desire identical goods.', 'Inflation increases purchasing power because prices and money value always move together upward.', 'Specialisation never occurs in service industries because only factories can divide tasks (alt 2.4/3).', 'If prices rise faster than incomes, households can buy fewer goods with the same nominal cash.', 'Inflation affects only foreign trade and never domestic purchasing power of euro cash.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Barter needs double coincidence of wants between trading parties.', 'FALSE — Inflation reduces real purchasing power; money buys less, not more.', 'FALSE — Call centres, hospitals, and restaurants all use division of labour.', 'TRUE — Faster price rises than income growth reduce real consumption capacity.', 'FALSE — Domestic cash purchasing power falls when general prices rise at home.'], '3/5', 13, 'full' ),
( '2.4', 'CASE 2.4.14', 'Voluntary donation park cleanup', 'A river park cleanup relies on voluntary donations; many residents enjoy cleaner paths without donating. Evaluate:', ARRAY['Residents who enjoy cleaner paths without paying illustrate the free-rider problem.', 'Public-good-like benefits may be underprovided when funding depends on voluntary contributions alone.', 'Tax financing could reduce free riding by requiring contributions from beneficiaries broadly.', 'Free riders exist only when money functions as medium of exchange and never with public services.', 'Voluntary funding always delivers optimal public-good levels without any shortfall.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Non-payers benefiting from cleanup funded by others are free riders.', 'TRUE — Voluntary schemes often underfund shared benefits.', 'TRUE — Compulsory tax spreads cost among users and non-users who still benefit.', 'FALSE — Free-rider logic applies to shared services regardless of how money functions.', 'FALSE — Voluntary donations frequently fall short of optimal provision.'], '3/5', 14, 'full' ),
( '2.4', 'CASE 2.4.15', 'Medium of exchange everyday', 'Shoppers pay euros for bread instead of trading socks directly with the baker. Evaluate:', ARRAY['Using euros avoids barter''s double coincidence of wants between bread and socks.', 'Money as medium of exchange separates the act of selling from the act of buying.', 'Street lighting financed by local tax can address free-rider problems of voluntary funding.', 'Medium of exchange is one of money''s three core functions alongside unit of account and store of value.', 'Without medium of exchange, every purchase would require direct matching of wants.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Money removes need for buyer and seller to want each other''s exact goods.', 'TRUE — Seller accepts money now and buys desired goods later from others.', 'TRUE — Tax spreads cost among beneficiaries who would otherwise free ride.', 'TRUE — Three functions are medium of exchange, unit of account, store of value.', 'TRUE — Barter requires reciprocal want alignment on each transaction.'], '2/5', 15, 'full' ),
( '2.4', 'CASE 2.4.16', 'ECB target recall', 'Evaluate precise claims about ECB inflation targeting:', ARRAY['The ECB aims for inflation slightly below 2% as its price-stability objective.', 'ECB target requires inflation to be exactly zero forever with no deviation allowed.', 'Price stability supports predictable purchasing power compared with high volatile inflation.', 'Inflation slightly below 2% is identical to hyperinflation in economic effect.', 'Central bank targets relate to macroeconomic stability of the general price level.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Slightly below 2% is the stated ECB aim.', 'FALSE — Target allows small positive inflation, not zero forever.', 'TRUE — Stable low inflation preserves purchasing power predictability.', 'FALSE — Hyperinflation destroys purchasing power; target stability contrasts sharply.', 'TRUE — Price-level stability is a macro policy goal.'], '3/5', 16, 'full' ),
( '2.4', 'CASE 2.4.17', 'Student grant transfer', 'Government pays living-cost grants to low-income students. Evaluate transfers:', ARRAY['Student grants are government transfers redistributing income toward a targeted group.', 'Transfers move purchasing power to recipients without necessarily providing a pure public good.', 'A transport subsidy lowers user fares by covering part of cost from public funds.', 'Grant income enters the circular flow as household income later spent on goods and services.', 'Transfers can pursue equity goals while remaining distinct from tax-funded defence or street lighting.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Grants shift resources to eligible students by policy design.', 'TRUE — Transfers support individuals; public goods are non-excludable shared services.', 'TRUE — Subsidies channel fiscal support to reduce prices or support producers or consumers.', 'TRUE — Grant spending flows through households to firms in the circular flow.', 'TRUE — Transfers pursue distributional aims separate from classic public-good provision.'], '3/5', 17, 'full' ),
( '2.4', 'CASE 2.4.18', 'Factory specialisation drawback', 'Workers on one repetitive bolt-tightening task report fatigue and cannot switch lines quickly. Evaluate:', ARRAY['Stored cash never loses purchasing power because nominal euro amounts stay unchanged on the note (alt 2.4/13).', 'Barter requires no matching of wants because any trade partners automatically desire identical goods (alt 2.4/14).', 'Specialisation always improves worker satisfaction with no possible downsides whatsoever.', 'Narrow task focus may limit workers'' transferable skills if jobs disappear.', 'Despite drawbacks, specialisation often lowers average production cost per unit.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Inflation reduces real value even when the printed number stays the same.', 'FALSE — Barter needs double coincidence of wants between trading parties.', 'FALSE — Monotony and skill narrowing are recognised drawbacks.', 'TRUE — Limited skill breadth is a risk when tasks are highly specialised.', 'TRUE — Productivity gains and lower unit cost remain the main advantage.'], '3/5', 18, 'full' ),
( '2.4', 'CASE 2.4.19', 'Specialisation in hospitals', 'Hospital splits surgery, diagnostics, and nursing into specialised departments. Evaluate:', ARRAY['Division of labour by medical specialty raises skill depth and often treatment efficiency.', 'Specialisation creates interdependence: diagnostics delay can postpone surgery schedules.', 'Specialisation never occurs in healthcare because every doctor must do every task.', 'Drawbacks can include coordination costs and bottlenecks between departments.', 'Despite coordination needs, specialisation typically improves output per specialist hour.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Focused departments develop deeper expertise.', 'TRUE — Delayed scans can block operating theatre slots.', 'FALSE — Healthcare relies heavily on specialised roles.', 'TRUE — Handoffs and queues are specialisation drawbacks.', 'TRUE — Expert focus raises productivity in complex services.'], '3/5', 19, 'full' ),
( '2.4', 'CASE 2.4.20', 'Public goods and free riders', 'Assess public goods, taxation, and free-rider problems:', ARRAY['Stored cash never loses purchasing power because nominal euro amounts stay unchanged on the note (alt 2.4/7).', 'Barter requires no matching of wants because any trade partners automatically desire identical goods (alt 2.4/8).', 'Specialisation never occurs in service industries because only factories can divide tasks (alt 2.4/9).', 'Street lighting is excludable for every passer-by, so free-rider problems never arise in practice.', 'Transfers and subsidies redistribute income or support specific groups without always being pure public goods.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Inflation reduces real value even when the printed number stays the same.', 'FALSE — Barter needs double coincidence of wants between trading parties.', 'FALSE — Call centres, hospitals, and restaurants all use division of labour.', 'FALSE — Street lighting is largely non-excludable; free-rider logic applies to many local public goods.', 'TRUE — Transfers and subsidies are fiscal tools distinct from but related to public-good provision.'], '3/5', 20, 'full' ),
( '2.4', 'CASE 2.4.21', 'Assembly line shutdown', 'A single missing chip halts an electronics assembly line where each worker performs one step. Evaluate:', ARRAY['Fine division of labour increases vulnerability when one specialised input or stage fails.', 'Specialisation raises productivity but creates interdependence among sequential tasks.', 'Comparing barter ratios among many goods is harder without a unit of account.', 'Monotonous single-step work can be a human drawback of extreme specialisation.', 'Despite shutdown risk, specialisation often lowers average cost when all stages run smoothly.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — One missing component stops tightly linked specialised stages.', 'TRUE — Sequential specialisation links output across dependent tasks.', 'TRUE — Common measurement simplifies relative value comparison.', 'TRUE — Repetitive single tasks may reduce job satisfaction.', 'TRUE — Productivity gains remain the efficiency advantage when supply is uninterrupted.'], '4/5', 21, 'full' ),
( '2.4', 'CASE 2.4.22', 'Division of labour', 'A car assembly line splits welding, painting, and electronics into separate tasks. Evaluate specialisation:', ARRAY['Specialisation never occurs in service industries because only factories can divide tasks.', 'Only foreign trade creates free-rider problems; domestic public services never do (alt 2.4/12).', 'Division of labour never creates drawbacks such as monotonous work or dependency on other stages.', 'Specialisation applies only to agriculture and cannot occur in manufacturing or services.', 'Interdependent assembly stages mean a breakdown in one station can halt the whole line.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Call centres, hospitals, and restaurants all use division of labour.', 'FALSE — Free-rider logic applies to domestic shared services such as parks and lighting.', 'FALSE — Drawbacks include boredom, skill narrowness, and supply-chain fragility.', 'FALSE — Specialisation appears in factories, offices, and services alike.', 'TRUE — Interdependence creates vulnerability to bottlenecks at one stage.'], '2/5', 22, 'full' ),
( '2.4', 'CASE 2.4.23', 'Circular flow income loop', 'Evaluate how income and spending connect households and firms:', ARRAY['Factor payments from firms to households become household income in the circular flow.', 'Household spending on goods and services returns revenue to firms, completing the loop.', 'The circular flow assumes households never supply labour or capital to production.', 'Money facilitates exchange within the flow as medium of exchange linking sales and purchases.', 'Saving and taxes can withdraw spending temporarily in extended circular-flow models.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Wages, rent, and profit flow to households as income.', 'TRUE — Consumption expenditure flows back to firms as sales revenue.', 'FALSE — Households supply factors and receive income for doing so.', 'TRUE — Monetary exchange connects production, income, and spending stages.', 'TRUE — Leakages like saving and tax appear in fuller diagrams.'], '3/5', 23, 'full' ),
( '2.4', 'CASE 2.4.24', 'Unit of account role', 'Prices in a supermarket are all labelled in euros. Evaluate money''s unit-of-account function:', ARRAY['Barter requires no matching of wants because any trade partners automatically desire identical goods (alt 2.4/2).', 'Unit of account means money serves as common measure for quoting prices and recording debts.', 'Unit of account requires barter because prices cannot be listed without trading goods directly.', 'Without a unit of account, comparing bread and cinema ticket values becomes harder.', 'Medium of exchange and unit of account are identical functions with no distinction.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — Barter needs double coincidence of wants between trading parties.', 'TRUE — Standard measure for prices and debts defines unit of account.', 'FALSE — Unit of account supports priced exchange; it does not require barter.', 'TRUE — Lack of common measure complicates value comparison among different items.', 'FALSE — Exchange facilitation and price measurement are distinct though related functions.'], '2/5', 24, 'full' ),
( '2.4', 'CASE 2.4.25', 'Municipal snow clearing', 'City clears snow from all residential streets using general taxation. Evaluate:', ARRAY['Street clearing after snow benefits many residents and is hard to charge individually at moment of use.', 'Free-rider issues arise if clearing relied on voluntary payments from each household.', 'Tax funding spreads cost across taxpayers to provide the shared service reliably.', 'Snow clearing is a pure private good with perfect excludability at all times.', 'Public goods financed by tax never appear in circular-flow diagrams with households.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Wide simultaneous benefit and difficulty of excludability fit public-good logic.', 'TRUE — Non-payers would still enjoy cleared streets under voluntary funding.', 'TRUE — Taxation compels broad contribution for shared infrastructure services.', 'FALSE — Many local services resemble public goods in practical excludability limits.', 'FALSE — Government tax and spend appears in extended circular-flow models.'], '3/5', 25, 'full' ),
( '2.4', 'CASE 2.4.26', 'Compare prices across aisles', 'Evaluate why a common currency unit matters for shopping:', ARRAY['Unit of account lets unlike products be priced in the same euro measure for comparison.', 'Unit of account function means euros physically store bread inside the coin itself.', 'Without common price units, barter ratios among many goods become complex quickly.', 'Medium of exchange and store of value are the only money functions; unit of account does not exist.', 'Inflation never affects unit-of-account function because price labels stay numeric.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Shared euro pricing simplifies comparing heterogeneous goods.', 'FALSE — Unit of account is measurement, not physical storage of goods in coins.', 'TRUE — Multiple barter ratios explode as product variety grows.', 'FALSE — Unit of account is one of the three standard functions.', 'FALSE — Inflation changes real meaning of numeric labels even if numbers change slowly.'], '2/5', 26, 'full' ),
( '2.4', 'CASE 2.4.27', 'Free rider street concert', 'A free outdoor concert is funded by sponsors; passers-by listen without paying. Evaluate:', ARRAY['Listeners enjoying music without contributing resemble free riders when funding is voluntary.', 'Pure public-good logic applies fully only if the concert is non-excludable and non-rival for all listeners.', 'Tax-funded public events could reduce free riding compared with purely voluntary sponsor models alone.', 'Free-rider problems arise only when inflation erodes purchasing power of tickets.', 'Non-paying enjoyment never creates funding shortfalls for open-access events.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Non-payers benefit from sponsor-funded provision.', 'TRUE — Full public-good label requires non-excludability and non-rivalry; open concerts approximate this locally.', 'TRUE — Compulsory public funding can spread cost among beneficiaries.', 'FALSE — Free riding concerns payment for shared benefits, not inflation of ticket prices.', 'FALSE — Voluntary funding often falls short when many free ride.'], '2/5', 27, 'full' ),
( '2.4', 'CASE 2.4.28', 'Barter limits', 'Two farmers swap eggs for vegetables without using money. Evaluate barter and money:', ARRAY['Inflation refers to one shop''s single price hike only, never to the general price level.', 'Specialisation never occurs in service industries because only factories can divide tasks (alt 2.4/15).', 'Because no euros change hands, this egg-for-vegetable swap involves no economic exchange at all.', 'Without money, storing value from perishable eggs into future purchases is harder than holding currency.', 'Barter economies never face problems comparing relative values of unlike goods.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Inflation is a general price-level phenomenon, not every individual price move.', 'FALSE — Call centres, hospitals, and restaurants all use division of labour.', 'FALSE — Barter is exchange even without monetary payment.', 'TRUE — Store-of-value function is weaker when goods are perishable or illiquid.', 'FALSE — Comparing egg value to vegetable value without a unit of account is difficult.'], '3/5', 28, 'full' ),
( '2.4', 'CASE 2.4.29', 'Integrated public finance recap', 'Assess combined concepts from circular flow, money, public goods, and specialisation:', ARRAY['Money functions as medium of exchange, unit of account, and store of value in the monetary economy.', 'Taxation can fund public goods and transfers when free riders would underfund voluntary provision.', 'Inflation erodes purchasing power; ECB aims for stability slightly below 2%.', 'Division of labour raises productivity but may create monotony and interdependence drawbacks.', 'Extended circular-flow models link households, firms, and government through income, spending, and tax.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Three standard functions of money.', 'TRUE — Tax addresses free-rider and funding gaps for shared services and redistribution.', 'TRUE — Inflation-purchasing power link and ECB target.', 'TRUE — Specialisation benefits and recognised drawbacks.', 'TRUE — Circular flow integrates private and public sectors monetarily.'], '2/5', 29, 'full' ),
( '2.4', 'CASE 2.4.30', 'Inflation versus single price hike', 'One café raises latte price ten cents; national inflation stays near ECB target. Evaluate:', ARRAY['Inflation refers to a general rise in the price level, not every individual price change alone.', 'A single ten-cent latte rise automatically equals economy-wide inflation by definition.', 'Persistent general price rises erode purchasing power of money over time.', 'ECB targets inflation slightly below 2% for the general index, not each shop''s menu.', 'Purchasing power depends on average prices faced by consumers broadly, not one item once.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Inflation is general price-level phenomenon.', 'FALSE — Individual price moves do not alone define macro inflation.', 'TRUE — Broad price rises reduce real value of nominal cash.', 'TRUE — ECB target applies to aggregate price stability.', 'TRUE — Real purchasing power reflects general price environment.'], '4/5', 30, 'full' ),
( '2.5', 'CASE 2.5.01', 'Consumer sovereignty test', 'Households shift spending toward plant-based foods; grocers expand vegan ranges. Evaluate:', ARRAY['Transformation never causes unemployment because market reforms instantly create perfect jobs for everyone (alt 2.5/6).', 'Consumer sovereignty means households never influence production because only planners decide output.', 'Firms respond to changing demand to earn revenue and profit in market systems.', 'In planned economies, identical consumer shifts always instantaneously change quotas without lag.', 'Prices and sales data help firms detect shifting preferences in market economies.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Historical transitions involved temporary dislocation and job losses during restructuring.', 'FALSE — Consumer demand guides market production through purchasing decisions.', 'TRUE — Profit motive aligns firm supply with paying consumer preferences.', 'FALSE — Planned systems may respond more slowly due to bureaucratic quota processes.', 'TRUE — Market sales signals inform production adjustments.'], '3/5', 1, 'full' ),
( '2.5', 'CASE 2.5.02', 'Eco-social renewable quota', 'Renewable energy share mandated; power exchanges still trade wholesale electricity competitively. Evaluate:', ARRAY['Eco-social market can set ecological quotas while keeping wholesale power markets.', 'Environmental mandates operate alongside price-based competition among generators where allowed.', 'Eco-social economy bans all electricity trading because ecology requires central planning only.', 'Market prices still coordinate dispatch among plants within regulatory constraints.', 'Social and eco-social models retain market mechanisms as coordination base.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Quotas plus markets combine ecology with price coordination.', 'TRUE — Regulation and competition coexist in eco-social design.', 'FALSE — Power exchanges continue under environmental rules.', 'TRUE — Prices guide operational choices within legal frameworks.', 'TRUE — Market coordination remains foundational.'], '3/5', 2, 'full' ),
( '2.5', 'CASE 2.5.03', 'Market versus planned systems', 'Evaluate core differences between market and planned economic systems:', ARRAY['Eco-social market economy eliminates all market prices because ecology requires pure central planning.', 'Central planning always matches consumer preferences perfectly with zero information problems (alt 2.5/7).', 'Market and planned systems are identical because both use money in every transaction.', 'Transformation from planned toward market systems often introduces private ownership and competition.', 'Planned systems never face any resource constraints because the centre can print unlimited orders.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Market prices and incentives often remain tools within environmental regulation.', 'FALSE — Planners historically struggled to gather local demand information that prices convey in markets.', 'FALSE — Ownership, incentives, and coordination mechanisms differ sharply between systems.', 'TRUE — Transition reforms typically expand markets, private property, and competitive entry.', 'FALSE — Planners still face scarce resources and must choose among competing uses.'], '3/5', 3, 'full' ),
( '2.5', 'CASE 2.5.04', 'Compare three market models', 'Evaluate distinctions among free, social, and eco-social market economies:', ARRAY['Free market economy emphasises private ownership, competition, and minimal intervention.', 'Social market economy adds social policy and welfare to preserve equity alongside markets.', 'Eco-social market economy adds environmental sustainability goals to the social market base.', 'Consumer sovereignty means household spending influences what firms produce through demand.', 'Transformation from planned systems moves toward market models, not deeper central planning.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Free market stresses private competition and limited intervention.', 'TRUE — Social market layers welfare and social partnership on markets.', 'TRUE — Eco-social adds ecological objectives to social market design.', 'TRUE — Purchasing choices steer production in market systems.', 'TRUE — Transition reforms liberalise and privatise rather than intensify planning.'], '3/5', 4, 'full' ),
( '2.5', 'CASE 2.5.05', 'Price liberalisation step', 'A transforming economy removes fixed bread prices, allowing shops to set levels. Evaluate:', ARRAY['Market and planned systems are identical because both use money in transactions (alt 2.5/5).', 'Market prices can signal shortages and surpluses to producers and consumers.', 'Liberalisation means all prices become zero because competition removes cost entirely.', 'Transition from planned systems often phases in price freedom gradually to limit shocks.', 'Consumer sovereignty can operate more fully when prices respond to demand and cost.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Coordination mechanisms—prices versus directives—differ fundamentally.', 'TRUE — Prices communicate scarcity and abundance.', 'FALSE — Liberalisation allows variation; it does not eliminate positive prices.', 'TRUE — Gradual reform reduces sudden affordability crises.', 'TRUE — Responsive prices align production with paying demand.'], '3/5', 5, 'full' ),
( '2.5', 'CASE 2.5.06', 'Free market economy traits', 'Analyze characteristics of a free market economy:', ARRAY['Free market economy means zero government role including no courts, defence, or public goods.', 'Market and planned systems are identical because both use money in transactions.', 'Free market economies ban all government activity including courts and national defence.', 'Eco-social market economy eliminates all market prices because ecology requires pure central planning (alt 2.5/10).', 'Prices in free markets help coordinate supply and demand without central direction.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Real market economies still need government for law, defence, and public goods.', 'FALSE — Coordination mechanisms—prices versus directives—differ fundamentally.', 'FALSE — Governments still provide law, defence, and public goods even in market economies.', 'FALSE — Market prices and incentives often remain tools within environmental regulation.', 'TRUE — Price signals coordinate decentralised decisions.'], '2/5', 6, 'full' ),
( '2.5', 'CASE 2.5.07', 'German social partners', 'Employers'' associations negotiate with unions under legal framework while firms compete in product markets. Evaluate social market:', ARRAY['Free market economy means zero government role including no courts, defence, or public goods (alt 2.5/8).', 'Co-determination and welfare institutions aim at social peace without abolishing private firms.', 'Social market means unions set all output quotas replacing consumer demand entirely.', 'Market competition among firms can coexist with worker representation rules.', 'Eco-social market would add stronger environmental standards to this social-market base.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Real market economies still need government for law, defence, and public goods.', 'TRUE — Social partnership complements, not replaces, market competition.', 'FALSE — Consumer demand and competition still drive most product allocation.', 'TRUE — Labour institutions and product-market competition operate together.', 'TRUE — Eco-social extends social market with ecology.'], '2/5', 7, 'full' ),
( '2.5', 'CASE 2.5.08', 'Universal basic services debate', 'Policy debate: expand public childcare while keeping private grocery markets. Evaluate mixed models:', ARRAY['Governments can provide selected services publicly while leaving most consumer goods to markets.', 'Social market economy tolerates mixed provision: public childcare plus competitive retail markets.', 'Exclusive state monopolies under planning may create shortages when prices are held below market-clearing levels.', 'Eco-social policies might subsidise green transport while competition continues among vehicle makers.', 'Consumer sovereignty mainly guides private competitive sectors like grocery retail.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Mixed economies combine public services with private markets sector by sector.', 'TRUE — Social market explicitly blends public social policy and market competition.', 'TRUE — Admin prices below equilibrium can cause excess demand and parallel unofficial markets.', 'TRUE — Eco-social tools can target ecology without ending automotive competition.', 'TRUE — Household spending steers competitive grocery assortment.'], '4/5', 8, 'full' ),
( '2.5', 'CASE 2.5.09', 'Social safety net in markets', 'Unemployment insurance and retraining vouchers coexist with competitive product markets. Evaluate social market features:', ARRAY['All OECD countries today operate as pure planned economies with no market competition.', 'Social market economy rejects all market competition in favour of pure central planning.', 'Planned systems never face scarcity because central authorities can order unlimited output of every good (alt 2.5/9).', 'Regulation of labour markets can coexist with firm competition for customers.', 'Social and eco-social market models both retain market coordination as a base.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — OECD economies are predominantly market-based with regulation and welfare overlays.', 'FALSE — Competition remains; social policy adds protection layers.', 'FALSE — Resource limits persist; planners must choose among competing uses.', 'TRUE — Labour rules and product-market competition operate in parallel.', 'TRUE — Market base plus policy overlays define these models.'], '2/5', 9, 'full' ),
( '2.5', 'CASE 2.5.10', 'Consumer boycott effect', 'Shoppers boycott a brand over labour practices; sales collapse and retailer delists it. Evaluate market economy mechanisms:', ARRAY['Consumer spending choices can punish firms that lose public trust, illustrating consumer sovereignty.', 'Boycotts prove planned economies operate in every retail sector because only planners can delist goods.', 'Profit motive leads retailers to respond when falling demand threatens revenue.', 'Market prices and sales volumes signal reputational damage faster than quota revisions would.', 'Social market economy still relies on consumer demand signals alongside labour regulation.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Spending shifts steer retailer assortment away from rejected brands.', 'FALSE — Retail delisting follows market demand collapse, not central plan edits.', 'TRUE — Revenue loss motivates delisting unpopular products.', 'TRUE — Sales data transmit consumer disapproval rapidly.', 'TRUE — Social regulation complements but does not replace demand signals.'], '4/5', 10, 'full' ),
( '2.5', 'CASE 2.5.11', 'Transformation unemployment spike', 'State factory closures during market transition temporarily raise joblessness before new private firms grow. Evaluate:', ARRAY['Transformation from planned to market systems can cause transitional unemployment during restructuring.', 'Social market policies may include retraining and benefits to cushion adjustment costs.', 'Transition never produces unemployment because market reforms instantly create perfect jobs for all.', 'Long-run market competition may raise efficiency even if short-run dislocation occurs.', 'Eco-social market adds environmental restructuring goals to the same transition challenges.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Privatisation and closure of inefficient state plants displace workers initially.', 'TRUE — Social market tools aim to ease transition social costs.', 'FALSE — Historical transitions involved significant temporary unemployment.', 'TRUE — Efficiency gains may follow after reallocation, despite short-run pain.', 'TRUE — Green transition adds parallel adjustment needs.'], '3/5', 11, 'full' ),
( '2.5', 'CASE 2.5.12', 'Eco-tax on carbon', 'Government imposes carbon price while keeping competitive electricity markets. Evaluate eco-social alignment:', ARRAY['Market and planned systems are identical because both use money in transactions (alt 2.5/12).', 'Eco-social market economy integrates ecological targets with market-based policy tools.', 'Carbon taxes eliminate all market prices because government sets every outcome directly.', 'Environmental goals in eco-social models can coexist with private firms competing on cost and quality.', 'Planned economies never use any environmental policy instruments at all.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — Coordination mechanisms—prices versus directives—differ fundamentally.', 'TRUE — Ecological aims embed in market economy policy design.', 'FALSE — Taxes adjust incentives; they do not replace market pricing broadly.', 'TRUE — Private competition continues under environmental regulation.', 'FALSE — Planned systems also used environmental rules, though coordination differed.'], '3/5', 12, 'full' ),
( '2.5', 'CASE 2.5.13', 'Social market economy', 'Evaluate the social market economy model:', ARRAY['Planned systems never face scarcity because central authorities can order unlimited output of every good.', 'Central planning always matches consumer preferences perfectly with zero information problems.', 'Social market economy abolishes all private firms and replaces them with central planning.', 'Transformation never causes unemployment because market reforms instantly create perfect jobs for everyone (alt 2.5/13).', 'Germany is often cited as an example of the social market economy approach.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Resource limits persist; planners must choose among competing uses.', 'FALSE — Planners historically struggled to gather local demand information that prices convey in markets.', 'FALSE — Private enterprise and competition remain central; planning does not replace markets.', 'FALSE — Historical transitions involved temporary dislocation and job losses during restructuring.', 'TRUE — Germany exemplifies social market principles in practice.'], '3/5', 13, 'full' ),
( '2.5', 'CASE 2.5.14', 'State farm to cooperative', 'Former state collective farms become farmer cooperatives selling on open markets. Evaluate transformation:', ARRAY['All OECD countries today operate as pure planned economies with no market competition (alt 2.5/11).', 'Market sales expose producers to consumer demand rather than fulfilment of plan quotas alone.', 'Transition always keeps 100% state ownership because privatisation never occurs in agriculture.', 'Profit incentive and price signals can guide crop choice after liberalisation.', 'Planned quota agriculture ignored local soil advantage because central targets overrode all information.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — OECD economies are predominantly market-based with regulation and welfare overlays.', 'TRUE — Open-market sales link revenue to consumer willingness to pay.', 'FALSE — Agricultural privatisation and cooperatives were common transition paths.', 'TRUE — Prices and profit motivate crop switching post-reform.', 'TRUE — Central quotas often misaligned with local conditions versus market feedback.'], '3/5', 14, 'full' ),
( '2.5', 'CASE 2.5.15', 'Planned steel quota surplus', 'Central plan targets steel output above what machinery factories can absorb. Evaluate:', ARRAY['Overplanned output creates surpluses when downstream demand is not coordinated through prices.', 'Market systems use price declines to signal excess supply and reduce production profitably.', 'Profit motive encourages firms to economise and respond to paying customers in competitive markets.', 'Transformation introduces market feedback to reduce persistent mismatch of intersectoral output.', 'Scarcity still applies under planning; producing too much steel wastes scarce inputs.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Quota chains can misalign upstream and downstream needs.', 'TRUE — Falling prices discourage overproduction in markets.', 'TRUE — Revenue and profit incentives align supply with demand.', 'TRUE — Market reforms aim to improve intersectoral coordination.', 'TRUE — Overproduction consumes limited resources inefficiently.'], '3/5', 15, 'full' ),
( '2.5', 'CASE 2.5.16', 'Eco-social housing standard', 'Government sets energy-efficiency rules while builders compete on design and price. Evaluate:', ARRAY['Central planning always matches consumer preferences perfectly with zero information problems (alt 2.5/14).', 'Environmental standards aim at sustainability without eliminating private builders competing for buyers.', 'Eco-social model requires abolishing all housing markets and assigning homes by central plan only.', 'Regulation sets minimum ecological performance; markets still compete above that floor.', 'Social market and eco-social market both preserve market coordination as a foundation.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Planners historically struggled to gather local demand information that prices convey in markets.', 'TRUE — Private firms compete within green standards.', 'FALSE — Housing markets continue under eco-social frameworks with rules.', 'TRUE — Standards set ecological floor; markets differentiate beyond it.', 'TRUE — Market base remains in both social and eco-social variants.'], '3/5', 16, 'full' ),
( '2.5', 'CASE 2.5.17', 'Voucher school choice', 'Parents use state vouchers to choose among competing private and public schools. Evaluate market elements in social policy:', ARRAY['Vouchers introduce consumer choice among providers within a publicly funded framework.', 'Social market economy can combine competition among schools with government financing.', 'Privatisation transfers state-owned enterprises toward private ownership in transition reforms.', 'Consumer sovereignty applies when families choose providers with voucher purchasing power.', 'Eco-social market could add environmental curriculum standards while retaining provider competition.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Vouchers let households choose among competing schools.', 'TRUE — Public funding plus provider competition fits social market logic.', 'TRUE — Selling or listing state firms is a hallmark of market transition.', 'TRUE — Family choice steers demand among competing schools.', 'TRUE — Environmental standards can overlay competitive education markets.'], '3/5', 17, 'full' ),
( '2.5', 'CASE 2.5.18', 'Central plan shortfall', 'Planned tractor factory misses component targets, halting farm deliveries nationwide. Evaluate planned-system weaknesses:', ARRAY['Transformation never causes unemployment because market reforms instantly create perfect jobs for everyone.', 'Free market economy means zero government role including no courts, defence, or public goods (alt 2.5/15).', 'Planned systems always outperform markets on flexibility and consumer responsiveness by definition.', 'Price signals in markets can relay local shortages faster than hierarchical quota revisions.', 'Transformation reforms often aim to reduce such rigidities by introducing market competition.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Historical transitions involved temporary dislocation and job losses during restructuring.', 'FALSE — Real market economies still need government for law, defence, and public goods.', 'FALSE — Planned systems often struggled with flexibility and consumer alignment historically.', 'TRUE — Prices aggregate dispersed information more rapidly in competitive markets.', 'TRUE — Transition seeks efficiency gains through market mechanisms.'], '4/5', 18, 'full' ),
( '2.5', 'CASE 2.5.19', 'Free market limits', 'Evaluate what free market economy does not mean:', ARRAY['Free market economy does not mean absence of all government; law, defence, and public goods remain.', 'Complete laissez-faire with zero regulation describes an ideal type, not most modern economies.', 'Social market and eco-social market deliberately add policy layers to competitive market base.', 'Planned economy and free market economy are the same system with different names only.', 'Transformation moves away from central planning toward greater market coordination and private incentives.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Governments enforce contracts and provide public goods in market economies.', 'TRUE — Real economies regulate externalities, safety, and competition rules.', 'TRUE — Social and eco-social variants add welfare and ecology to markets.', 'FALSE — Planning uses directives; markets use prices and private incentives—distinct systems.', 'TRUE — Transition liberalises and privatises rather than expanding planning.'], '3/5', 19, 'full' ),
( '2.5', 'CASE 2.5.20', 'Eco-social market economy', 'Assess the eco-social market economy concept:', ARRAY['Planned systems never face scarcity because central authorities can order unlimited output of every good (alt 2.5/2).', 'Planned systems never face scarcity because central authorities can order unlimited output of every good (alt 2.5/16).', 'Eco-social market economy eliminates prices entirely so environmental goals need no economic trade-offs.', 'Environmental taxes or cap-and-trade can use market instruments within an eco-social framework.', 'Transformation from planned systems is unrelated to eco-social market ideas because they apply only to island economies.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Resource limits persist; planners must choose among competing uses.', 'FALSE — Resource limits persist; planners must choose among competing uses.', 'FALSE — Market prices and incentives often remain tools for environmental policy.', 'TRUE — Market-based environmental instruments fit within regulated market frameworks.', 'FALSE — Eco-social concepts apply to advanced market economies adapting policy, not only hypothetical cases.'], '3/5', 20, 'full' ),
( '2.5', 'CASE 2.5.21', 'Privatisation auction', 'State telecom monopoly sells shares publicly; new entrants offer mobile plans. Evaluate transition:', ARRAY['Privatisation transfers ownership from state to private investors in transition reforms.', 'New entrants introduce competition where a state monopoly existed under planning.', 'Legal exclusive bus franchises create monopoly-like local power on designated routes.', 'Consumer sovereignty improves when households choose among competing mobile plans and prices.', 'Market prices for plans reflect cost and demand rather than fixed admin tariffs alone.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Share sales move telecom toward private ownership.', 'TRUE — Liberalisation allows competing carriers.', 'TRUE — Statutory exclusivity blocks rival entry on the same lines.', 'TRUE — Choice among plans aligns supply with consumer preferences.', 'TRUE — Competitive pricing replaces uniform admin rates.'], '3/5', 21, 'full' ),
( '2.5', 'CASE 2.5.22', 'Planned economy coordination', 'In a centrally planned system, ministries set steel output quotas. Evaluate:', ARRAY['Market and planned systems are identical because both use money in transactions (alt 2.5/19).', 'Planned economies historically involved state ownership of major industries in many cases.', 'Consumer preferences automatically dominate production under planning without any information problem.', 'Transformation toward markets often privatises state firms and liberalises prices gradually.', 'Planning eliminates scarcity because the state can order unlimited production of every good.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Coordination mechanisms—prices versus directives—differ fundamentally.', 'TRUE — State ownership of key sectors was common in planned systems.', 'FALSE — Planners may lack accurate local demand information that prices convey in markets.', 'FALSE — Transition introduces markets and private ownership reforms over time.', 'FALSE — Resource limits persist; planning chooses among scarce inputs.'], '2/5', 22, 'full' ),
( '2.5', 'CASE 2.5.23', 'State housing queue', 'Under planning, families wait years for assigned flats; after reform, private developers build for sale. Evaluate:', ARRAY['Central allocation queues replaced market housing supply and pricing in many planned systems.', 'Market transformation allows private developers to respond to paying demand with new builds.', 'Consumer sovereignty in housing strengthens when buyers choose location and quality voluntarily.', 'Planned assignment always matched family preferences perfectly with zero mismatch ever recorded.', 'Price signals after reform guide how much housing is built and where.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Admin allocation created long waits versus market supply response.', 'TRUE — Private development links construction to market demand and finance.', 'TRUE — Buyers choose units matching preferences and budgets.', 'FALSE — Queues and poor matches were chronic planned-economy housing problems.', 'TRUE — Prices coordinate land, labour, and capital toward housing demand.'], '4/5', 23, 'full' ),
( '2.5', 'CASE 2.5.24', 'Private property rights', 'Evaluate role of private ownership in market systems:', ARRAY['Free market economy means zero government role including no courts, defence, or public goods (alt 2.5/1).', 'All OECD countries today operate as pure planned economies with no market competition (alt 2.5/18).', 'Market economies require zero government enforcement of contracts and property rights.', 'Transformation from planned economies often restores or clarifies private property rights.', 'Without ownership incentives, profit motive and consumer responsiveness weaken in allocation.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Real market economies still need government for law, defence, and public goods.', 'FALSE — OECD economies are predominantly market-based with regulation and welfare overlays.', 'FALSE — Markets need legal institutions to enforce property and contracts.', 'TRUE — Property reform is central to market transition.', 'TRUE — Incentives linking effort to reward drive market responsiveness.'], '3/5', 24, 'full' ),
( '2.5', 'CASE 2.5.25', 'Black market under planning', 'Consumers queue for state-priced shoes; unofficial sellers offer imports at higher prices. Evaluate:', ARRAY['Eco-social market economy eliminates all market prices because ecology requires pure central planning (alt 2.5/17).', 'Black markets emerge when official prices do not clear demand at allocated supply.', 'Planned economies never experience shortages because quotas always match preferences perfectly.', 'Transformation toward market pricing aims to reduce such parallel unofficial markets over time.', 'Price signals in open markets can align supply with demand more directly.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Market prices and incentives often remain tools within environmental regulation.', 'TRUE — Unofficial markets satisfy excess demand at higher prices.', 'FALSE — Planning frequently misestimated demand and supply locally.', 'TRUE — Liberalisation reduces incentive for parallel illegal trade.', 'TRUE — Market prices help clear markets without chronic shortages.'], '4/5', 25, 'full' ),
( '2.5', 'CASE 2.5.26', 'Mixed economy reality', 'Most modern economies combine markets with public education and healthcare funding. Evaluate:', ARRAY['Eco-social market economy eliminates all market prices because ecology requires pure central planning (alt 2.5/3).', 'Central planning always matches consumer preferences perfectly with zero information problems (alt 2.5/21).', 'Social market economy explicitly embraces this mix of competition plus social policy.', 'Planned economy elements like total state ownership dominate every OECD country today without exception.', 'Eco-social market adds environmental policy goals to mixed market frameworks.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Market prices and incentives often remain tools within environmental regulation.', 'FALSE — Planners historically struggled to gather local demand information that prices convey in markets.', 'TRUE — Social market model formalises the competitive-plus-welfare mix.', 'FALSE — OECD countries are predominantly market-based with regulation, not fully planned.', 'TRUE — Eco-social variant adds sustainability to mixed market design.'], '4/5', 26, 'full' ),
( '2.5', 'CASE 2.5.27', 'Profit motive response', 'Fuel prices rise; taxi firms invest in smaller efficient cars. Evaluate market incentives:', ARRAY['Transformation never causes unemployment because market reforms instantly create perfect jobs for everyone (alt 2.5/20).', 'Consumer sovereignty still operates as riders choose cheaper fares where competition exists.', 'Profit motive exists only in planned economies because state firms never care about cost.', 'Market prices transmit fuel cost changes to operators deciding fleet composition.', 'Social market economy retains profit incentives while adding social regulation and welfare.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Historical transitions involved temporary dislocation and job losses during restructuring.', 'TRUE — Riders'' spending choices reward competitive efficient operators.', 'FALSE — State firms faced budget pressures too, but incentives differed under planning.', 'TRUE — Price changes signal input scarcity to producers.', 'TRUE — Social market keeps profit drive within regulated competitive framework.'], '2/5', 27, 'full' ),
( '2.5', 'CASE 2.5.28', 'Post-transition privatisation', 'A former planned economy sells state factories to private investors and opens markets. Evaluate transformation:', ARRAY['All OECD countries today operate as pure planned economies with no market competition (alt 2.5/4).', 'Free market economy means zero government role including no courts, defence, or public goods (alt 2.5/22).', 'Transition never changes ownership structures because all firms must remain state property forever.', 'Introducing competition can improve efficiency after monopolistic state production.', 'Market transformation happens overnight with zero adjustment costs or unemployment ever.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — OECD economies are predominantly market-based with regulation and welfare overlays.', 'FALSE — Real market economies still need government for law, defence, and public goods.', 'FALSE — Transition explicitly shifts toward private and mixed ownership.', 'TRUE — Competition pressures can raise productivity after state monopoly.', 'FALSE — Transition involves gradual reforms and social adjustment costs.'], '3/5', 28, 'full' ),
( '2.5', 'CASE 2.5.29', 'Integrated systems comparison', 'Evaluate combined system concepts:', ARRAY['Market versus planned describes how resource allocation is coordinated economy-wide.', 'Free market emphasises private ownership, competition, and consumer sovereignty.', 'Social market adds welfare and social partnership without abolishing competition.', 'Eco-social market adds environmental sustainability to social market foundations.', 'Transformation reforms shift planned economies toward market mechanisms and private incentives over time.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Core coordination distinction between systems.', 'TRUE — Free market pillars: property, competition, consumer demand.', 'TRUE — Social layer on competitive base.', 'TRUE — Ecological layer on social market.', 'TRUE — Transition path from planning to markets.'], '2/5', 29, 'full' ),
( '2.5', 'CASE 2.5.30', 'Model selection recap', 'Assess summary claims about economic systems in Fuhrmann Ch.2.5:', ARRAY['Market economies rely mainly on private decisions and price signals to allocate resources.', 'Planned economies rely on central directives and state targets rather than market prices.', 'Free, social, and eco-social market economies are variants building on market coordination.', 'Transformation from planned toward market systems involves privatisation and price liberalisation reforms.', 'Eco-social market economy ignores environmental goals and copies pure laissez-faire exactly.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Decentralised prices and ownership typify market allocation.', 'TRUE — Central planning sets output and input assignments.', 'TRUE — Three market variants differ by social and ecological policy depth.', 'TRUE — Transition reforms introduce markets and private property.', 'FALSE — Eco-social explicitly adds environmental sustainability to market base.'], '2/5', 30, 'full' ),
( '2.6', 'CASE 2.6.01', 'Harvest glut surplus', 'Mild weather yields bumper apple harvest; orchards cannot sell all crates at current price. Evaluate:', ARRAY['A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/4).', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/13).', 'Surplus means consumers want more apples than farmers picked at the going price.', 'Rightward supply shift from bumper crop can create surplus if price is sticky downward.', 'Lower equilibrium price clears surplus by raising quantity demanded and discouraging some supply.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Surplus is excess supply, not excess demand.', 'TRUE — Bigger harvest shifts supply right, potentially creating surplus at old price.', 'TRUE — Price fall moves market toward new equilibrium.'], '3/5', 1, 'full' ),
( '2.6', 'CASE 2.6.02', 'Number of sellers supply shift', 'Two new ride-hail apps enter a city, increasing ride service supply at each fare. Evaluate:', ARRAY['More competing suppliers shift market supply rightward for ride services.', 'Entry is a supply shifter increasing quantity supplied at each price.', 'More apps shift demand left because consumers hate choice by law of demand.', 'Rightward supply with stable demand tends to lower equilibrium fare and raise rides quantity.', 'Supply shifters include number of producers, technology, and input costs.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Additional providers increase market supply.', 'TRUE — Entry shifts supply curve right.', 'FALSE — More choice does not automatically reduce demand for rides.', 'TRUE — Greater supply at same demand lowers clearing price.', 'TRUE — Standard supply shifter categories.'], '3/5', 2, 'full' ),
( '2.6', 'CASE 2.6.03', 'Law of demand', 'Evaluate the law of demand and demand curve behaviour:', ARRAY['A change in the good''s own price shifts the entire demand curve rather than moving along it.', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/3).', 'The law of demand claims quantity demanded rises when price rises, other things equal.', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/16).', 'Demand shifters such as income changes shift the whole curve rather than moving along it.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — That describes an upward demand curve, contradicting the law of demand.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'TRUE — Non-price factors shift demand left or right.'], '3/5', 3, 'full' ),
( '2.6', 'CASE 2.6.04', 'Minimum wage labour market', 'Legal minimum wage set above previous equilibrium in low-skill labour market. Evaluate:', ARRAY['A binding minimum wage above equilibrium can create labour surplus—unemployment excess supply.', 'Surplus in labour market means quantity of labour supplied exceeds quantity demanded at the floor wage.', 'Minimum wage below equilibrium is non-binding and does not create shortage of workers by itself.', 'Labour markets follow supply and demand logic like goods markets though institutions differ.', 'Price floor above equilibrium prevents wage from falling to clear the market.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Wage floor above market-clearing level can leave more workers seeking jobs than hired.', 'TRUE — Excess labour supply at mandated wage is unemployment surplus.', 'TRUE — Non-binding floors do not distort clearing below them.', 'TRUE — Supply-demand framework applies to labour.', 'TRUE — Floor stops wage adjustment that would absorb surplus.'], '4/5', 4, 'full' ),
( '2.6', 'CASE 2.6.05', 'Concert ticket scalping', 'Official price fixed below equilibrium; scalpers resell at higher market-clearing levels. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/14).', 'Secondary market price reflects higher equilibrium where quantity demanded meets limited supply.', 'Shortage means unsold tickets pile up at the box office because nobody wants them.', 'Price ceilings below equilibrium prevent market from clearing at official rate.', 'Surplus and shortage analysis applies to services like concerts as well as goods.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'TRUE — Scalper price approximates market-clearing level given fixed official supply.', 'FALSE — Shortage is too much demand, not unsold excess supply.', 'TRUE — Ceiling blocks upward price adjustment to equilibrium.', 'TRUE — Supply-demand logic covers tickets and services.'], '3/5', 5, 'full' ),
( '2.6', 'CASE 2.6.06', 'Law of supply', 'Analyze the law of supply and supply curve behaviour:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/29).', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/30).', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/31).', 'Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/32).', 'A change in the good''s own price causes movement along the supply curve.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'TRUE — Own-price changes trace movement along supply.'], '2/5', 6, 'full' ),
( '2.6', 'CASE 2.6.07', 'Popularity fad demand shift', 'Viral trend spikes demand for a reusable bottle at every price level. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/17).', 'Movement along demand requires a change in the bottle''s own price, not social media alone.', 'Fad shifts supply left because factories dislike trendy products by law of supply.', 'Rightward demand with unchanged supply tends to raise equilibrium price and quantity.', 'After fad fades, demand may shift left again lowering equilibrium price.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'TRUE — Own-price change needed for movement along curve.', 'FALSE — Fads affect willingness to buy; they do not directly shift producer cost curves.', 'TRUE — Demand increase with fixed supply raises clearing price and quantity traded.', 'TRUE — Demand retreat reverses pressure on price.'], '3/5', 7, 'full' ),
( '2.6', 'CASE 2.6.08', 'Market types recap', 'Evaluate claims about markets and coordination:', ARRAY['Markets are arrangements where buyers and sellers exchange goods, services, or factors at prices.', 'Physical shops, wholesale halls, and online platforms are all market forms.', 'Supply and demand interaction determines equilibrium price and quantity in competitive markets.', 'Law of demand and law of supply describe directional responses to own-price changes, ceteris paribus.', 'Demand and supply shifters change curves; own-price changes move along curves.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Markets coordinate exchange through price.', 'TRUE — Multiple market formats exist.', 'TRUE — Equilibrium clears plans at balancing price.', 'TRUE — Standard directional laws for own-price changes.', 'TRUE — Shift versus movement distinction is fundamental.'], '2/5', 8, 'full' ),
( '2.6', 'CASE 2.6.09', 'Online marketplace platform', 'Evaluate types of markets including virtual ones:', ARRAY['Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/6).', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/15).', 'Markets exist only as literal town squares with no digital or institutional forms allowed.', 'Specialised markets include labour, goods, services, and financial asset markets.', 'Price mechanism coordinates plans in competitive markets through supply and demand interaction.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Modern markets include online and institutional trading systems.', 'TRUE — Different market types segment goods, labour, and finance.', 'TRUE — Prices coordinate quantities in market systems.'], '2/5', 9, 'full' ),
( '2.6', 'CASE 2.6.10', 'Interest-sensitive investment', 'Rate cut cheapens business loans; firms expand capacity supplying more goods later. Evaluate links:', ARRAY['Lower interest rates reduce investment cost, potentially shifting future supply rightward.', 'Rate cuts also boost demand for interest-sensitive goods like housing and durables.', 'Interest rates never connect to inflation control because money has no supply curve.', 'Anti-inflation tightening raises rates to moderate demand and credit growth.', 'Monetary policy uses rates partly because too much money growth can fuel inflation.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Cheaper credit encourages capacity expansion—a supply-side effect over time.', 'TRUE — Lower rates stimulate demand for credit-sensitive purchases.', 'FALSE — Monetary policy and inflation link through demand and money growth channels.', 'TRUE — Rate hikes cool inflationary demand pressure.', 'TRUE — Excess money growth relative to output can raise general prices.'], '3/5', 10, 'full' ),
( '2.6', 'CASE 2.6.11', 'Own-price only movement', 'Evaluate distinction between curve shift and movement along curve:', ARRAY['Change in good''s own price causes movement along demand or supply, not a curve shift.', 'Income, tastes, and substitute prices shift demand curves.', 'Input costs, technology, and number of sellers shift supply curves.', 'Own-price change shifts both demand and supply simultaneously by definition always.', 'Confusing shift with movement misidentifies equilibrium comparative statics.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Own price is axis variable; movement stays on same curve.', 'TRUE — Non-own-price demand determinants shift demand.', 'TRUE — Non-own-price cost and tech factors shift supply.', 'FALSE — Own-price change moves along curves; it does not shift both by rule.', 'TRUE — Analytical errors follow from mixing the two concepts.'], '3/5', 11, 'full' ),
( '2.6', 'CASE 2.6.12', 'Inflation too much money', 'Prices rise broadly after rapid money supply growth while output lags. Evaluate:', ARRAY['Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/18).', 'General price level rise reduces purchasing power of each euro held.', 'Inflation always improves purchasing power because higher prices mean richer consumers automatically.', 'Central banks may raise interest rates to cool inflation by reducing spending and credit growth.', 'Inflation affects only one shop''s menu and never the general price level.'], ARRAY[false, true, false, true, false], ARRAY['FALSE — Inflation is general price-level rise, not every individual price move.', 'TRUE — Broad price rises erode real value of money balances.', 'FALSE — Inflation reduces real purchasing power unless nominal incomes keep pace.', 'TRUE — Higher interest rates are a standard anti-inflation macro tool.', 'FALSE — Inflation refers to general price-level increases, not isolated menu changes.'], '3/5', 12, 'full' ),
( '2.6', 'CASE 2.6.13', 'Market equilibrium', 'A city bus ticket market settles at 2.50 euros where quantity demanded equals quantity supplied. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears.', 'Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/5).', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/19).', 'Equilibrium eliminates scarcity entirely so no buyer ever faces a budget constraint again.', 'Surplus puts downward pressure on price; shortage puts upward pressure toward equilibrium.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Scarcity persists; equilibrium clears the market at a given price, not unlimited abundance.', 'TRUE — Surplus and shortage pressures push price toward equilibrium.'], '3/5', 13, 'full' ),
( '2.6', 'CASE 2.6.14', 'Fuel tax supply for taxis', 'Higher fuel tax raises taxi operating cost; fewer rides offered at each fare. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/20).', 'If demand unchanged, equilibrium fare tends to rise and quantity of rides falls.', 'Fuel tax shifts demand right because passengers enjoy paying more for identical trips.', 'Own-fare increase for taxis alone causes movement along supply, not shift from fuel tax.', 'Input-cost shocks are classic supply shifters in service markets.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'TRUE — Left supply and stable demand raise price, cut quantity.', 'FALSE — Passengers do not automatically demand more trips when costs rise.', 'TRUE — Fare change moves along curve; tax changes shift it.', 'TRUE — Cost shocks shift supply in goods and services alike.'], '3/5', 14, 'full' ),
( '2.6', 'CASE 2.6.15', 'Equilibrium adjustment story', 'Evaluate step-by-step market adjustment from disequilibrium:', ARRAY['At price above equilibrium, surplus leads sellers to cut price toward equilibrium.', 'At price below equilibrium, shortage leads buyers to bid price up toward equilibrium.', 'Equilibrium is where quantity demanded equals quantity supplied with stable price tendency.', 'Surplus means quantity supplied exceeds quantity demanded at the current price.', 'Shortage means quantity demanded exceeds quantity supplied at the current price.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Unsold inventory pushes price down from above equilibrium.', 'TRUE — Queues and bidding push price up from below equilibrium.', 'TRUE — Clearing condition defines equilibrium.', 'TRUE — Excess supply definition of surplus.', 'TRUE — Excess demand definition of shortage.'], '3/5', 15, 'full' ),
( '2.6', 'CASE 2.6.16', 'Farmers'' market Saturday', 'Physical farmers'' market matches local growers with city shoppers each weekend. Evaluate:', ARRAY['A weekly farmers'' market is a physical place market for local produce.', 'Prices adjust toward equilibrium where planned sales match planned purchases by closing time.', 'Physical markets cannot experience shortage or surplus because goods are visible on tables.', 'Supply and demand at the market determine clearing prices for seasonal produce.', 'Virtual markets are the only valid market form in modern economics.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Designated venue and regular trading hours define a place market.', 'TRUE — Unsold stock or sell-outs signal surplus or shortage pressures.', 'FALSE — Visible unsold crates indicate surplus; early sell-outs indicate shortage at listed price.', 'TRUE — Seasonal supply and shopper demand set market prices.', 'FALSE — Physical and virtual markets both exist.'], '2/5', 16, 'full' ),
( '2.6', 'CASE 2.6.17', 'Sticky rent ceiling', 'Rent capped below market equilibrium; applicants queue for scarce flats. Evaluate:', ARRAY['Rent ceiling below equilibrium creates housing shortage—excess demand for flats.', 'Landlords supply fewer rental units at capped rent than at market-clearing rent.', 'Shortage manifests as waiting lists and difficulty finding available flats.', 'Ceiling above equilibrium is non-binding and market clears normally without shortage.', 'Price floors and ceilings can prevent market from reaching equilibrium price.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Below-market cap yields excess demand.', 'TRUE — Lower mandated return reduces quantity of rental housing supplied.', 'TRUE — Queues signal shortage at controlled price.', 'TRUE — Non-binding caps do not distort clearing above them.', 'TRUE — Controls block price adjustment mechanism.'], '4/5', 17, 'full' ),
( '2.6', 'CASE 2.6.18', 'Rate hike mortgage effect', 'Central bank raises rates; variable mortgage holders cut discretionary spending. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/8).', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/21).', 'Interest rate changes never affect consumer spending because borrowing is impossible for households.', 'Tighter credit can shift demand left for interest-sensitive goods like housing and durables.', 'Anti-inflation policy trades short-term demand slowdown against price stability goals.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Household borrowing and spending clearly respond to interest costs.', 'TRUE — Housing and durables demand often falls when rates rise.', 'TRUE — Policy accepts demand moderation to stabilise prices.'], '3/5', 18, 'full' ),
( '2.6', 'CASE 2.6.19', 'Wholesale electricity market', 'Power producers bid into daily wholesale exchange; price clears at matching quantity. Evaluate:', ARRAY['Wholesale power exchange is an institutional virtual market for electricity.', 'Market-clearing price equates aggregate quantity demanded with quantity supplied.', 'Electricity markets cannot experience surplus because electrons are invisible.', 'Supply and demand for power respond to fuel costs, weather demand, and plant availability.', 'Surplus power at high price would push wholesale price downward toward equilibrium.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Exchange platform coordinates many buyers and sellers without physical trading floor.', 'TRUE — Clearing price balances bids to buy and offers to sell.', 'FALSE — Oversupply at price depresses wholesale price like other markets.', 'TRUE — Cost and demand shifters move power supply and demand curves.', 'TRUE — Standard surplus price pressure applies.'], '3/5', 19, 'full' ),
( '2.6', 'CASE 2.6.20', 'Demand shifter: income rise', 'Household incomes rise after a wage agreement; demand for restaurant meals increases at every price. Evaluate:', ARRAY['Individual shop price changes alone define economy-wide inflation without reference to general price level.', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/7).', 'Income rise always shifts demand left because richer households buy less of everything.', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/22).', 'Equilibrium meal price may rise after demand shifts right if supply unchanged.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Normal goods demand increases with income; inferior goods are the exception.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'TRUE — Rightward demand shift with fixed supply tends to raise equilibrium price.'], '3/5', 20, 'full' ),
( '2.6', 'CASE 2.6.21', 'Integrated market recap', 'Assess combined supply-demand and inflation concepts:', ARRAY['Markets coordinate through supply and demand determining equilibrium price and quantity.', 'Surplus and shortage push price toward equilibrium when flexible.', 'Ceteris paribus, a higher own price of a good reduces quantity demanded along the demand curve.', 'Inflation—too much money chasing too few goods—erodes purchasing power broadly.', 'Higher interest rates can fight inflation by cooling demand and credit growth.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Core market coordination mechanism.', 'TRUE — Disequilibrium price adjustment logic.', 'TRUE — This is the law of demand for own-price increases.', 'TRUE — Monetary excess and real output mismatch inflation story.', 'TRUE — Anti-inflation rate policy link.'], '2/5', 21, 'full' ),
( '2.6', 'CASE 2.6.22', 'Supply shifter: energy cost', 'Bakeries face higher oven fuel costs; less bread supplied at each price. Evaluate:', ARRAY['A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/1).', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/9).', 'Input cost rise shifts demand left because consumers dislike expensive flour spiritually.', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/25).', 'Leftward supply shift with unchanged demand tends to raise equilibrium bread price.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Fuel costs affect producers'' supply, not consumers'' demand directly.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'TRUE — Reduced supply with same demand raises clearing price.'], '2/5', 22, 'full' ),
( '2.6', 'CASE 2.6.23', 'Expectations demand shift', 'News of future sugar tax shifts demand left for sugary drinks today as consumers anticipate change. Evaluate:', ARRAY['Expected future policy can shift current demand if consumers change buying plans early.', 'Anticipated future price rise may shift demand right today for some storable goods.', 'Expectations never shift demand because only today''s own price matters by law of demand.', 'Demand shift from expectations differs from movement along curve from today''s own price.', 'Leftward demand shift tends to lower current equilibrium price if supply unchanged.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Forward-looking buyers may reduce purchases before tax begins.', 'TRUE — Expecting higher future cost can increase current buying for storable items.', 'FALSE — Expectations are a recognised demand shifter.', 'TRUE — Own-price change moves along; expectation changes shift curve.', 'TRUE — Weaker demand lowers clearing price with fixed supply.'], '4/5', 23, 'full' ),
( '2.6', 'CASE 2.6.24', 'Substitute price shift', 'Coffee bean price spike raises espresso price; some customers switch to tea. Evaluate demand:', ARRAY['A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/10).', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/24).', 'Coffee and tea can be substitutes; relative price changes redirect some spending.', 'Substitute price rise shifts coffee supply left automatically with no separate demand effect.', 'Market equilibrium for tea may rise in price if tea demand shifts right with fixed tea supply.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'TRUE — Relative price change steers consumers toward alternatives.', 'FALSE — Bean cost affects coffee supply; consumer switching is demand-side substitution.', 'TRUE — Higher tea demand with unchanged tea supply tends to raise tea equilibrium price.'], '4/5', 24, 'full' ),
( '2.6', 'CASE 2.6.25', 'Hyperinflation wheelbarrow cash', 'Rapid money growth makes prices rise daily; cash buys less each week. Evaluate inflation:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/23).', 'Too much money relative to available goods can drive such general price surges.', 'Hyperinflation improves store-of-value function of currency because holding cash becomes smarter.', 'Central banks combat high inflation partly by tightening monetary policy and raising interest rates.', 'Inflation at this pace affects all cash holders'' real balances, not one shop only.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'TRUE — Monetary excess versus output capacity fuels inflation.', 'FALSE — Hyperinflation destroys store-of-value function of currency.', 'TRUE — Tighter policy and higher rates cool overheated demand and inflation.', 'TRUE — General price level phenomenon, economy-wide.'], '4/5', 25, 'full' ),
( '2.6', 'CASE 2.6.26', 'Tech improvement supply shift', 'Automated picking cuts apple harvest labour cost; more apples supplied at each price. Evaluate:', ARRAY['Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/12).', 'Individual shop price changes alone define economy-wide inflation without reference to general price level (alt 2.6/27).', 'Cheaper harvesting raises supply and tends to lower equilibrium price if demand unchanged.', 'Technology shifts demand left because consumers dislike automated fruit by definition.', 'Rightward supply with fixed demand increases equilibrium quantity and usually lowers price.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Inflation is general price-level rise, not every individual price move.', 'FALSE — Inflation is general price-level rise, not every individual price move.', 'TRUE — Greater supply at same demand lowers clearing price.', 'FALSE — Automation affects producer cost side; consumer demand need not fall automatically.', 'TRUE — Standard comparative statics of supply increase.'], '3/5', 26, 'full' ),
( '2.6', 'CASE 2.6.27', 'Complement price change', 'Printer price falls; demand for ink cartridges rises at each cartridge price. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/26).', 'Complement price fall for printer increases demand for paired cartridge good.', 'Cartridge own-price fall would shift cartridge demand right rather than move along it.', 'Complement relations differ from substitute relations where relative price rise redirects demand.', 'Equilibrium cartridge price may rise if demand shifts right with unchanged cartridge supply.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'TRUE — Cheaper printers encourage printer ownership raising cartridge needs.', 'FALSE — Own-price fall of cartridges moves along demand; printer price is separate shifter.', 'TRUE — Substitutes rise in demand when competitor price rises; complements when paired good cheapens.', 'TRUE — Demand boost with fixed supply tends to raise equilibrium price.'], '4/5', 27, 'full' ),
( '2.6', 'CASE 2.6.28', 'Ice cream shortage heatwave', 'Heatwave boosts ice cream demand while supply unchanged; queues form at kiosks. Evaluate:', ARRAY['Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/2).', 'Equilibrium eliminates scarcity so buyers face no budget constraints after the market clears (alt 2.6/11).', 'Shortage means sellers cannot sell all stock and must dump unsold ice cream daily.', 'A change in the good''s own price shifts the entire demand curve rather than moving along it (alt 2.6/28).', 'Equilibrium adjustment may raise price until quantity demanded equals quantity supplied again.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'FALSE — Scarcity persists; equilibrium clears plans at a given price, not unlimited abundance.', 'FALSE — Shortage is excess demand, not excess supply unsold.', 'FALSE — Own-price changes cause movement along a fixed curve; shifters are non-price factors.', 'TRUE — Price rise reduces quantity demanded and can restore balance.'], '3/5', 28, 'full' ),
( '2.6', 'CASE 2.6.29', 'Full market mechanism', 'Evaluate the complete competitive market story:', ARRAY['Buyers and sellers interact in markets that may be physical or virtual.', 'Demand slopes downward; supply slopes upward under normal conditions.', 'Equilibrium price clears the market; surplus and shortage drive adjustment.', 'Non-price factors shift curves; own-price changes trace movements along curves.', 'Excess money growth can fuel inflation; interest-rate policy may counter inflationary pressure.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Market forms and participation.', 'TRUE — Standard curve slopes reflecting laws of demand and supply.', 'TRUE — Clearing and adjustment dynamics.', 'TRUE — Analytical shift/movement distinction.', 'TRUE — Inflation-monetary policy linkage from chapter themes.'], '2/5', 29, 'full' ),
( '2.6', 'CASE 2.6.30', 'Law violations trap', 'Spot statements violating laws of supply and demand:', ARRAY['Ceteris paribus, higher own price of a normal good reduces quantity demanded.', 'Ceteris paribus, higher own price increases quantity supplied by producers.', 'Higher own price of a good always shifts its demand curve rightward automatically.', 'Lower input costs shift supply rightward, increasing quantity supplied at each price.', 'Equilibrium occurs where quantity demanded equals quantity supplied.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Law of demand for own-price increase.', 'TRUE — Law of supply for own-price increase.', 'FALSE — Own-price rise causes movement along demand, not a rightward shift.', 'TRUE — Cost reduction increases supply at each price.', 'TRUE — Market clearing definition.'], '4/5', 30, 'full' ),
( '2.7', 'CASE 2.7.01', 'Breakfast cereal aisle', 'Four brands control most shelf space; each watches rivals'' promotions closely. Evaluate:', ARRAY['Monopoly sellers are price takers because they face many rivals selling identical goods.', 'Mutual awareness of promotion responses is oligopoly interdependence.', 'Four-brand dominance is perfect competition because cereal boxes are physical goods.', 'Cartel collusion is legal if firms meet privately and agree identical prices voluntarily.', 'Differentiated brands within oligopoly compete on marketing as well as price.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'TRUE — Promotion reactions show strategic interdependence.', 'FALSE — Physical goods can still be oligopoly if few firms dominate.', 'FALSE — Voluntary price fixing is cartel conduct and generally illegal.', 'TRUE — Product differentiation coexists with few-firm structure.'], '3/5', 1, 'full' ),
( '2.7', 'CASE 2.7.02', 'Oligopoly game theory hint', 'Two petrol station chains on a motorway always match each other''s litre price within an hour. Evaluate:', ARRAY['Two dominant chains on a corridor resemble duopoly with visible strategic pricing.', 'Quick price matching suggests interdependent decision-making characteristic of oligopoly.', 'Matching prices publicly without secret agreement may still be lawful competitive parallelism.', 'Any price similarity proves illegal cartel regardless of evidence of coordination.', 'Many independent rural stations with no mutual awareness better fit perfect competition locally.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Two-chain corridor is duopoly-like oligopoly.', 'TRUE — Rapid matching reflects strategic rivalry.', 'TRUE — Parallel pricing can occur without secret cartel agreement.', 'FALSE — Similar prices alone do not prove illegal collusion.', 'TRUE — Many unconnected small stations align with competitive structure.'], '3/5', 2, 'full' ),
( '2.7', 'CASE 2.7.03', 'Perfect competition assumptions', 'Evaluate assumptions of perfect competition:', ARRAY['Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/3).', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/4).', 'Perfect competition requires one dominant seller setting price for the entire market.', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/7).', 'Near-perfect competition appears in some agricultural markets with standardised grain grades.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'TRUE — Commodity agriculture approximates near-perfect competition.'], '3/5', 3, 'full' ),
( '2.7', 'CASE 2.7.04', 'Coffee roaster collusion case', 'Four regional roasters convicted of fixing wholesale bean prices in secret meetings. Evaluate:', ARRAY['Secret wholesale price fixing among rivals is cartel behaviour and illegal.', 'Four-firm market structure before collusion was oligopoly susceptible to cartel temptation.', 'Open independent pricing by oligopolists differs from illegal secret cartel collusion.', 'Cartels aim to raise prices toward monopoly outcome by eliminating competitive undercutting.', 'Competition law targets cartels to protect buyers from collusive inflation of price.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Secret fixing meetings are classic cartel conduct.', 'TRUE — Four sellers is oligopoly where collusion risk arises.', 'TRUE — Rivalry without agreement is lawful; secret coordination is cartel conduct.', 'TRUE — Collusion mimics monopoly pricing jointly.', 'TRUE — Enforcement preserves competitive pricing benefits.'], '4/5', 4, 'full' ),
( '2.7', 'CASE 2.7.05', 'Online marketplace many sellers', 'Thousands of small phone-case sellers compete on one platform with identical case specs. Evaluate:', ARRAY['Many small sellers of standardised cases approximate near-perfect competition within that niche.', 'Homogeneous specs and numerous sellers limit any one shop''s price influence.', 'Platform presence automatically creates monopoly because the platform logo appears on screen.', 'Price-taking behaviour emerges when no single small seller moves market price alone.', 'Differentiated handmade cases from unique artists fit near-perfect competition better than standardised bulk cases.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Many sellers plus similar products approach competitive model.', 'TRUE — Standardisation and numbers support price-taking.', 'FALSE — Platform hosts many sellers; marketplace structure is not automatic monopoly of each seller.', 'TRUE — Individual small sellers are price takers in large homogeneous niches.', 'FALSE — Unique artisan differentiation moves toward monopolistic competition, not perfect competition.'], '3/5', 5, 'full' ),
( '2.7', 'CASE 2.7.06', 'Local water utility', 'Only one piped water company serves a small town under licence. Evaluate market structure:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/5).', 'Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/6).', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/10).', 'Perfect competition with dozens of interchangeable water pipe networks exists in every small town.', 'Monopoly power can allow price above marginal cost if regulation permits.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'FALSE — Duplicate pipe networks are impractical; competition is limited locally.', 'TRUE — Lack of rivals can raise price unless regulated.'], '2/5', 6, 'full' ),
( '2.7', 'CASE 2.7.07', 'Electricity transmission grid', 'One grid operator owns transmission lines in a region by law. Evaluate:', ARRAY['Legal monopoly over transmission lines is monopoly-like infrastructure structure.', 'Duplicate competing transmission grids in the same area are usually uneconomic, reinforcing monopoly-like status.', 'Transmission monopoly means generation and retail must also be monopoly with zero competition ever.', 'Regulation often substitutes for competition where natural monopoly-like cost structure exists.', 'Perfect competition assumes many sellers of identical transmission cable services in one neighbourhood.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Single grid operator is regulated monopoly-like network.', 'TRUE — High fixed cost and duplication waste support single network.', 'FALSE — Generation and retail may compete even if transmission is monopoly-like.', 'TRUE — Regulation replaces market competition where monopoly-like cost conditions hold.', 'FALSE — Many parallel grids contradict cost realities.'], '3/5', 7, 'full' ),
( '2.7', 'CASE 2.7.08', 'Structure comparison recap', 'Evaluate summary market-structure claims:', ARRAY['Monopoly: one dominant seller, often local monopoly-like utilities or exclusive concessions.', 'Oligopoly: few large interdependent sellers, e.g. mobile carriers or concentrated brands.', 'Cartel: illegal collusion among oligopolists to coordinate prices or output.', 'Perfect competition: many price takers, homogeneous product, free entry; near-perfect in some agriculture.', 'Market power generally rises as number of competing sellers falls and differentiation or barriers rise.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Monopoly/local monopoly-like definitions and examples.', 'TRUE — Oligopoly few-firm interdependence.', 'TRUE — Cartel illegality and collusion meaning.', 'TRUE — Perfect/near-perfect competition assumptions and ag examples.', 'TRUE — General market-power intuition across structures.'], '2/5', 8, 'full' ),
( '2.7', 'CASE 2.7.09', 'Municipal bus monopoly', 'City awards exclusive bus franchise; no rival buses on same routes legally. Evaluate:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/14).', 'Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/15).', 'Exclusive franchise instantly creates perfect competition because passengers choose routes freely.', 'Regulators may cap fares when monopoly or franchise power would otherwise overcharge riders.', 'Monopoly-like structures can arise from law as well as from natural cost conditions.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'FALSE — Exclusivity contradicts many-seller perfect competition.', 'TRUE — Fare regulation offsets local market power.', 'TRUE — Statutory exclusivity creates monopoly-like conditions.'], '2/5', 9, 'full' ),
( '2.7', 'CASE 2.7.10', 'Cartel versus consortium', 'Evaluate legal cooperation versus illegal cartel:', ARRAY['Illegal cartels fix prices or output secretly among competitors to raise profits jointly.', 'Research joint ventures sharing technology may be lawful if they do not fix product prices collusively.', 'All cooperation among firms is automatically an illegal cartel with zero lawful exceptions ever.', 'Competition authorities investigate evidence of collusive meetings and identical pricing patterns.', 'Oligopoly becomes cartel when coordination replaces independent competitive rivalry on price or output.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Secret price or output fixing defines cartel.', 'TRUE — Some R&D consortia differ from price-fixing cartels if competition on product markets continues.', 'FALSE — Not all cooperation is cartel; legality depends on conduct and market effects.', 'TRUE — Authorities examine collusion evidence.', 'TRUE — Collusion transforms oligopoly rivalry into cartel.'], '4/5', 10, 'full' ),
( '2.7', 'CASE 2.7.11', 'Egg farmers many sellers', 'Open-air market: fifty egg vendors sell identical grade A eggs at a posted market price. Evaluate:', ARRAY['Many small vendors selling standardised eggs at common price approximates perfect competition.', 'Individual vendors are price takers relative to the market clearing price.', 'Fifty vendors with identical eggs represent monopoly because eggs are food.', 'Standardised grade A labelling supports homogeneous-product assumption.', 'Exclusive franchise to one egg vendor would convert the market to monopoly-like structure.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Many sellers, homogeneous product, common price fit competitive model.', 'TRUE — Individual stall cannot move market price alone.', 'FALSE — Many sellers contradict monopoly definition.', 'TRUE — Grade standardisation reduces differentiation.', 'TRUE — Exclusive rights would eliminate competitive many-seller structure.'], '2/5', 11, 'full' ),
( '2.7', 'CASE 2.7.12', 'Assumption audit', 'Spot violations of perfect competition assumptions:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/17).', 'Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/18).', 'Free entry and exit without barriers is a perfect competition condition.', 'Perfect competition assumes each firm is a price taker unable to move market price alone.', 'Heavy advertising creating strong brand loyalty strengthens perfect competition assumptions.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'TRUE — Easy entry is standard assumption.', 'TRUE — Price-taking behaviour is definitional for competitive firms.', 'FALSE — Brand loyalty and differentiation contradict homogeneous-product assumption.'], '4/5', 12, 'full' ),
( '2.7', 'CASE 2.7.13', 'Mobile carrier oligopoly', 'Three national carriers control 95% of mobile subscriptions. Evaluate:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/8).', 'Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/9).', 'Oligopoly always means exactly two firms globally by mathematical definition only.', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/13).', 'Cartels—oligopolists cooperating illegally to fix prices—are prohibited in competitive law.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'FALSE — Oligopoly means few sellers, not necessarily exactly two (that is duopoly, a special case).', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'TRUE — Collusive cartels are illegal in many jurisdictions.'], '3/5', 13, 'full' ),
( '2.7', 'CASE 2.7.14', 'Premium smartphone duo', 'Two firms sell most premium smartphones globally; launch dates and prices align strategically. Evaluate:', ARRAY['Duopoly-like dominance in premium smartphones fits oligopoly with strategic launches.', 'Interdependent timing and pricing reflect oligopoly rivalry or tacit coordination risks.', 'Premium phones are homogeneous wheat grains, so the market is perfect competition.', 'Many small phone-case sellers on a platform define the structure of premium handset manufacturing.', 'Illegal cartel would require evidence of secret price or output agreement among phone makers.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — Two major premium vendors indicate oligopoly/duopoly features.', 'TRUE — Launch and price alignment may signal strategic interaction.', 'FALSE — Differentiated premium devices are not homogeneous commodities.', 'FALSE — Case sellers'' market structure differs from handset oligopoly.', 'TRUE — Cartel requires collusive agreement, not mere parallel competition.'], '3/5', 14, 'full' ),
( '2.7', 'CASE 2.7.15', 'Rail freight three operators', 'Three firms haul most rail freight nationally; each publishes tariff responses to rivals. Evaluate:', ARRAY['Three-firm dominance with published tariff reactions indicates oligopoly structure.', 'Strategic price responses differentiate oligopoly from many-firm perfect competition.', 'Many small egg vendors selling identical grade A eggs at a common market price approximate perfect competition.', 'Independent tariff publishing can be competitive oligopoly rivalry rather than collusion.', 'Cartel requires coordinated action to fix prices or divide markets illegally.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — High freight concentration aligns with oligopoly.', 'TRUE — Tariff reactions show mutual strategic consideration.', 'TRUE — Numerous sellers and homogeneous product fit the competitive model.', 'TRUE — Transparent rivalry may remain lawful competition.', 'TRUE — Collusion element distinguishes cartel from oligopoly.'], '3/5', 15, 'full' ),
( '2.7', 'CASE 2.7.16', 'Farmers'' grain co-op auction', 'Hundreds of farmers sell identical grade wheat at weekly co-op auction to many mill buyers. Evaluate:', ARRAY['Many sellers and buyers trading standardised wheat at auction approximates near-perfect competition.', 'Individual farmers are price takers at the co-op clearing price each week.', 'Auction with two farmers total would still be perfect competition because wheat is a crop.', 'Standardised grading reduces product differentiation supporting competitive model.', 'Brand advertising campaigns differentiate wheat varieties into luxury fashion-like oligopoly always.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Numerous traders plus homogeneous grade fit near-perfect competition.', 'TRUE — No single small farmer moves weekly auction price alone.', 'FALSE — Two sellers would be duopoly, not many-seller perfect competition.', 'TRUE — Grade standards homogenise the product.', 'FALSE — Commodity wheat lacks brand differentiation like fashion oligopolies.'], '2/5', 16, 'full' ),
( '2.7', 'CASE 2.7.17', 'Perfect competition price taker', 'Evaluate price-taking behaviour under perfect competition:', ARRAY['A price-taking firm accepts the market price and cannot profitably charge much above it alone.', 'Many small sellers of homogeneous products lead to individual firms being price takers.', 'Exclusive airport parking concession creates monopoly-like power at the terminal location.', 'Free entry tends to erode economic profits toward normal levels in competitive markets long run.', 'Near-perfect agricultural commodity markets illustrate price-taking among many farmers.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Individual firm has negligible market share to set price.', 'TRUE — Many homogeneous sellers create competitive price taking.', 'TRUE — Single concessionaire with captive demand is local monopoly-like.', 'TRUE — Entry pressure limits sustained supernormal profit in competitive model.', 'TRUE — Commodity markets exemplify price-taking behaviour.'], '4/5', 17, 'full' ),
( '2.7', 'CASE 2.7.18', 'Steel industry trio', 'Three steelmakers account for most national output and track each other''s capacity announcements. Evaluate:', ARRAY['Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/1).', 'Capacity announcements signal strategic interdependence typical of oligopoly.', 'Three-firm concentration is monopoly because monopoly always means more than ten firms.', 'Independent competitive pricing without considering rivals defines oligopoly behaviour.', 'Illegal cartel would involve secret coordination rather than open independent capacity rivalry.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — Single dominant seller describes monopoly, not perfect competition.', 'TRUE — Watching rivals'' capacity is strategic oligopoly behaviour.', 'FALSE — Monopoly is one dominant seller, not three large rivals.', 'FALSE — Ignoring rivals suggests competitive markets; oligopoly features mutual awareness.', 'TRUE — Open rivalry differs from secret cartel collusion.'], '3/5', 18, 'full' ),
( '2.7', 'CASE 2.7.19', 'Structure mislabel trap', 'Identify the mislabelled market-structure statement in this list:', ARRAY['One firm with exclusive piped-water rights in a town represents monopoly-like local market structure.', 'Three national mobile network operators serving most subscribers fit oligopoly rather than perfect competition.', 'Secret meetings where mill owners fix wholesale prices constitute an illegal cartel under competition law.', 'Many wheat farmers selling a standard grade at auction approximate near-perfect competition in that commodity market.', 'Four dominant cereal brands that watch each other''s promotions are perfect competition because boxes look similar on shelf.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Exclusive utility fits monopoly-like local structure.', 'TRUE — Three national carriers fit oligopoly.', 'TRUE — Secret fixing is cartel.', 'TRUE — Commodity auction with many farmers fits near-perfect competition.', 'FALSE — Few dominant brands with strategic rivalry is oligopoly, not perfect competition.'], '4/5', 19, 'full' ),
( '2.7', 'CASE 2.7.20', 'Cartel raid headline', 'Regulators fine flour mills for secretly agreeing uniform wholesale prices. Evaluate:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/11).', 'Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/12).', 'Open price competition among many small bakeries is cartel behaviour by definition.', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/16).', 'Oligopoly becomes cartel when firms collude rather than compete independently.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'FALSE — Many small competing bakeries typify competitive markets, not cartels.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'TRUE — Collusion distinguishes cartel from independent oligopoly rivalry.'], '3/5', 20, 'full' ),
( '2.7', 'CASE 2.7.21', 'Local cable broadband', 'One cable company wired every street; no second cable network built. Evaluate:', ARRAY['Single wired broadband network locally is monopoly-like infrastructure structure.', 'High sunk cost of duplicate cables discourages second network—natural monopoly-like conditions.', 'Wireless and fibre rivals may compete at retail level even if one cable network exists locally.', 'Brand-heavy luxury fashion with few design houses fits oligopoly or monopolistic competition, not wheat-style perfect competition.', 'Regulators may impose service or price rules on monopoly-like local network operators.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Sole wired network supplier is local monopoly-like.', 'TRUE — Duplicating wired plant is often uneconomic.', 'TRUE — Substitute technologies can limit power even with one cable network.', 'TRUE — Differentiation and few brands contradict homogeneous many-seller assumptions.', 'TRUE — Regulation addresses local market power of networks.'], '3/5', 21, 'full' ),
( '2.7', 'CASE 2.7.22', 'Wheat exchange floor', 'Standardised wheat grades trade on a commodity exchange with many farmers and buyers. Evaluate:', ARRAY['Perfect competition requires one dominant seller setting price for the entire market (dedup 2.7/1).', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/19).', 'Every retail clothing shop worldwide is a perfect competition market because clothes exist.', 'Free entry and many participants push individual farmers toward price-taking behaviour.', 'Differentiated designer fashion brands with few luxury houses resemble perfect competition.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Single dominant seller describes monopoly, not perfect competition.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'FALSE — Retail clothing varies by brand and differentiation; not perfect competition.', 'TRUE — Many sellers limit individual price influence.', 'FALSE — Luxury differentiated brands fit monopolistic competition or oligopoly, not perfect competition.'], '2/5', 22, 'full' ),
( '2.7', 'CASE 2.7.23', 'Monopoly price maker', 'Evaluate monopoly pricing power versus competition:', ARRAY['Monopoly faces downward-sloping demand and can choose price-quantity point along it.', 'Competitive price takers treat market price as given and adjust quantity supplied.', 'Monopoly has zero market power if customers can buy perfect substitutes from many rivals.', 'Local monopoly-like concessions may charge above marginal cost when substitutes are distant.', 'Cartel collusion tries to replicate monopoly joint pricing among separate firms illegally.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Single seller influences price along market demand curve.', 'TRUE — Price takers respond to given market price.', 'FALSE — Many close substitutes would erode monopoly power; monopoly implies limited substitutes.', 'TRUE — Geographic or legal isolation enables supra-competitive pricing.', 'TRUE — Cartel seeks monopoly outcome through collusion.'], '3/5', 23, 'full' ),
( '2.7', 'CASE 2.7.24', 'Village pharmacy distance', 'Only one pharmacy within twenty kilometres; villagers buy prescriptions there. Evaluate:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/2).', 'Customers facing long travel may accept higher prices or limited hours from the single seller.', 'Local monopoly-like power requires global dominance in worldwide pharmaceutical production.', 'Many competing pharmacies on the same village square would restore near-perfect competition locally.', 'Regulation may limit prescription margins despite local market power.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'TRUE — Limited alternatives reduce customer bargaining power locally.', 'FALSE — Local market power does not require global industry dominance.', 'FALSE — One square with many pharmacies would be competitive; isolation prevents that.', 'TRUE — Price rules can constrain exploitation of local power.'], '3/5', 24, 'full' ),
( '2.7', 'CASE 2.7.25', 'Agricultural standardisation', 'Why are crop markets cited as near-perfect competition examples? Evaluate:', ARRAY['Standardised grades make wheat from many farms homogeneous from buyer''s view.', 'Many small farmers each supply a tiny market share, limiting individual price influence.', 'All retail markets for clothing and cars are near-perfect competition for the same reason as wheat.', 'Seasonal harvest shifts supply but many sellers remain price takers at exchange price.', 'Brand-heavy luxury goods markets mirror wheat exchanges in structure and assumptions.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Grading homogenises commodity output.', 'TRUE — Large number of small producers supports price-taking.', 'FALSE — Differentiated retail goods often fit oligopoly or monopolistic competition, not wheat model.', 'TRUE — Supply shifts move market price; individual farmers still take price.', 'FALSE — Luxury branded goods contradict homogeneous-product assumption.'], '2/5', 25, 'full' ),
( '2.7', 'CASE 2.7.26', 'Airline route duopoly', 'Two airlines fly a thin international route; each matches fare changes within hours. Evaluate:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods (alt 2.7/20).', 'Monopoly sellers are price takers because they face many rivals selling identical goods (alt 2.7/21).', 'Two carriers on a route prove perfect competition with price-taking behaviour.', 'Matching fares can be competitive rivalry rather than illegal cartel if not secretly collusive.', 'Secret agreement to fix identical fares would be illegal cartel conduct.'], ARRAY[false, false, false, true, true], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Monopoly faces downward-sloping demand and has pricing power; price takers have many rivals.', 'FALSE — Two sellers are not ''many'' price takers required for perfect competition.', 'TRUE — Parallel pricing can arise from competition without collusion.', 'TRUE — Secret coordinated fixing crosses into illegal cartel.'], '4/5', 26, 'full' ),
( '2.7', 'CASE 2.7.27', 'Local vs global structure', 'Evaluate local monopoly-like versus global oligopoly distinctions:', ARRAY['A sole town pharmacy can be monopoly-like locally despite global pharmaceutical competition existing.', 'Global smartphone manufacturing may be oligopoly even if local phone-case sellers are many and competitive.', 'Market structure is always identical at every geographic scale by definition.', 'Exclusive airport parking is monopoly-like at the terminal even if city has many car parks elsewhere.', 'Perfect competition requires global monopoly of one firm to ensure price taking.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Geographic market definition matters; local sole seller can be monopoly-like.', 'TRUE — Structure differs by product and geographic market boundary.', 'FALSE — Local and global structures can differ for the same industry.', 'TRUE — Captive airport demand defines relevant local market narrowly.', 'FALSE — Perfect competition requires many sellers, not one global monopolist.'], '4/5', 27, 'full' ),
( '2.7', 'CASE 2.7.28', 'Regional airport parking', 'One firm holds the exclusive airport parking concession contract. Evaluate:', ARRAY['All retail clothing markets worldwide are perfect competition because clothes are physical goods.', 'Perfect competition requires one dominant seller setting price for the entire market (alt 2.7/22).', 'Exclusive contracts never create market power because airports are public buildings.', 'Monopoly-like local concessions can sustain prices above competitive levels without regulation.', 'Perfect competition requires many parking operators at the identical terminal location simultaneously.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Differentiated brands and few dominant firms contradict perfect competition.', 'FALSE — Single dominant seller describes monopoly, not perfect competition.', 'FALSE — Exclusive rights confer market power despite public airport ownership.', 'TRUE — Lack of rivals allows supra-competitive pricing within contract scope.', 'FALSE — Physical exclusivity prevents many same-spot competitors.'], '3/5', 28, 'full' ),
( '2.7', 'CASE 2.7.29', 'Market structures master recap', 'Assess integrated market-structure concepts from Fuhrmann 2.7:', ARRAY['Monopoly or local monopoly-like: one dominant seller, limited substitutes, possible regulation.', 'Oligopoly: few large interdependent firms, strategic pricing and output decisions.', 'Cartel: illegal collusion among oligopolists fixing price or output jointly.', 'Perfect competition: many price takers, homogeneous product, free entry; near-perfect in standardised agriculture.', 'Market power tends to rise as seller count falls, entry barriers rise, and products differentiate.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Monopoly/local monopoly-like summary.', 'TRUE — Oligopoly interdependence summary.', 'TRUE — Cartel illegality and collusion summary.', 'TRUE — Perfect/near-perfect competition and agricultural examples.', 'TRUE — Market-power intuition across structures.'], '2/5', 29, 'full' ),
( '2.7', 'CASE 2.7.30', 'Enforcement deterrence', 'Heavy fines announced after cement producer cartel bust. Evaluate policy goals:', ARRAY['Cartel penalties aim to deter oligopolists from secret collusion on price or output.', 'Legal independent pricing in oligopoly remains permitted without collusive agreement.', 'All oligopolies are automatically legal cartels even when firms compete aggressively.', 'Consumers benefit when cartel price fixing is blocked and competitive undercutting resumes.', 'Near-perfect competition in standardised commodities contrasts with cartel behaviour in concentrated industries.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Deterrence reduces collusion incentives in concentrated markets.', 'TRUE — Rivalry without agreement is lawful oligopoly conduct.', 'FALSE — Oligopoly structure alone is not cartel; collusion is separate.', 'TRUE — Ending collusion lowers artificially high prices toward competitive levels.', 'TRUE — Competitive commodity markets differ from collusive concentrated ones.'], '3/5', 30, 'full' )
